window.APP_LIBRARY={"plants":[{"id":1,"name":"Manzanilla","uses":"digestión lenta, gases, cólicos, dolores menstruales leves, nervios, ojos irritados.","part":"flores.","how":"infusión 1 cda en 200 ml de agua, 5-7 min. Para ojos: compresas tibias.","precaution":"alérgicos a asteráceas, evitar.","substitute":"cedrón, menta.","sourcePage":13,"image":"./assets/plants/manzanilla.webp","imageData":"data:image/webp;base64,"},{"id":2,"name":"Menta / Hierbabuena","uses":"empachos, digestiones pesadas, náuseas, congestión leve.","part":"hojas.","how":"infusión corta (no más de 5 min). Para vapor: hojas en agua caliente.","precaution":"no en bebés ni lactantes muy chicos.","substitute":"boldo + limón.","sourcePage":14,"image":"./assets/plants/menta-hierbabuena.webp","imageData":"data:image/webp;base64,"},{"id":3,"name":"Tilo","uses":"nervios, ansiedad suave, dificultad para dormir, presión emocional.","part":"flores.","how":"infusión suave antes de dormir.","precaution":"hipotensos: usar con moderación.","substitute":"manzanilla + lavanda.","sourcePage":15,"image":"./assets/plants/tilo.webp","imageData":"data:image/webp;base64,"},{"id":4,"name":"Lavanda","uses":"estrés, insomnio, migraña por tensión, piel irritada.","part":"flores.","how":"infusión para beber (muy suave) o mejor uso externo: baño, almohadilla, spray.","precaution":"no tomar en exceso en embarazo.","substitute":"tilo.","sourcePage":16,"image":"./assets/plants/lavanda.webp","imageData":"data:image/webp;base64,"},{"id":5,"name":"Romero","uses":"circulación, memoria, caída del cabello, resfríos, dolor muscular.","part":"hojas.","how":"infusión o macerado en aceite para masajes.","precaution":"epilépticos y embarazadas: consultar. No exceder.","substitute":"salvia.","sourcePage":17,"image":"./assets/plants/romero.webp","imageData":"data:image/webp;base64,"},{"id":6,"name":"Salvia","uses":"garganta inflamada, aftas, sudoración excesiva, digestión pesada.","part":"hojas.","how":"gárgaras e infusión.","precaution":"no usar en lactancia prolongada.","substitute":"tomillo.","sourcePage":18,"image":"./assets/plants/salvia.webp","imageData":"data:image/webp;base64,"},{"id":7,"name":"Tomillo","uses":"tos, bronquios cargados, infecciones respiratorias leves, garganta.","part":"hojas y sumidades.","how":"infusión + miel, o vapor.","precaution":"no abusar en embarazo.","substitute":"orégano.","sourcePage":19,"image":"./assets/plants/tomillo.webp","imageData":"data:image/webp;base64,"},{"id":8,"name":"Orégano","uses":"antiséptico respiratorio, digestivo, cólicos.","part":"hojas.","how":"infusión o como condimento en comidas.","precaution":"en aceite esencial es muy fuerte.","substitute":"tomillo.","sourcePage":20,"image":"./assets/plants/oregano.webp","imageData":"data:image/webp;base64,"},{"id":9,"name":"Eucalipto","uses":"descongestionar, abrir vías respiratorias.","part":"hojas.","how":"vapor e inhalación; en jarabes caseros.","precaution":"NO en bebés, NO aceite esencial directo.","substitute":"menta + tomillo.","sourcePage":21,"image":"./assets/plants/eucalipto.webp","imageData":"data:image/webp;base64,"},{"id":10,"name":"Jengibre fresco","uses":"resfriíos iniciales, defensas, náuseas, mareos, circulación.","part":"raíz.","how":"decocción 10 min o rallado en infusiones.","precaution":"hipertensos y anticoagulados: consultar.","substitute":"cúrcuma + limón.","sourcePage":22,"image":"./assets/plants/jengibre.webp","imageData":"data:image/webp;base64,"},{"id":11,"name":"Cúrcuma","uses":"inflamación, articulaciones, hígado perezoso.","part":"rizoma.","how":"en leche dorada, comidas o decocción con pimienta.","precaution":"cálculos biliares: consultar.","substitute":"jengibre.","sourcePage":23,"image":"./assets/plants/curcuma.webp","imageData":"data:image/webp;base64,"},{"id":12,"name":"Caléndula","uses":"piel irritada, heridas, dermatitis, aftas.","part":"flores.","how":"pomadas, macerado en aceite, infusión para enjuagues.","precaution":"chequear alergias.","substitute":"manzanilla.","sourcePage":24,"image":"./assets/plants/calendula.webp","imageData":"data:image/webp;base64,"},{"id":13,"name":"Aloe vera (sábila)","uses":"quemaduras leves, irritaciones, digestión.","part":"gel interno.","how":"uso externo directo; para beber, en poca cantidad.","precaution":"NO usar la cáscara (aloína) en embarazadas.","substitute":"caléndula.","sourcePage":25,"image":"./assets/plants/aloe-vera.webp","imageData":"data:image/webp;base64,"},{"id":14,"name":"Boldo","uses":"hígado, digestiones pesadas, empacho.","part":"hojas.","how":"infusión corta después de comer.","precaution":"no usar por largos períodos; no embarazadas.","substitute":"diente de león.","sourcePage":26,"image":"./assets/plants/boldo.webp","imageData":"data:image/webp;base64,"},{"id":15,"name":"Diente de león","uses":"depurar, retención de líquidos, hígado.","part":"hojas y raíz.","how":"infusión de hojas o decocción de raíz.","precaution":"cálculos biliares, consultar.","substitute":"cola de caballo + perejil.","sourcePage":27,"image":"./assets/plants/diente-de-leon.webp","imageData":"data:image/webp;base64,"},{"id":16,"name":"Ortiga","uses":"anemia leve, caída de cabello, depurar, alergias.","part":"hojas secas.","how":"infusión (una vez seca no pica) o en shampoo casero.","precaution":"hipertensos: moderar.","substitute":"romero + diente de león.","sourcePage":28,"image":"./assets/plants/ortiga.webp","imageData":"data:image/webp;base64,"},{"id":17,"name":"Hinojo","uses":"gases, digestión en niños más grandes, cólicos.","part":"semillas.","how":"infusión de 1 cdita machacada.","precaution":"lactantes → consultar.","substitute":"anís estrellado.","sourcePage":29,"image":"./assets/plants/hinojo.webp","imageData":"data:image/webp;base64,"},{"id":18,"name":"Anís estrellado","uses":"gases, digestión, tos con flema.","part":"fruto.","how":"infusión corta, tapada.","precaution":"no abusar en niños.","substitute":"hinojo.","sourcePage":30,"image":"./assets/plants/anis-estrellado.webp","imageData":"data:image/webp;base64,"},{"id":19,"name":"Canela","uses":"mejorar circulación, sube temperatura, dolores menstruales.","part":"corteza.","how":"decocción o en leche.","precaution":"no abusar en embarazo.","substitute":"jengibre.","sourcePage":31,"image":"./assets/plants/canela.webp","imageData":"data:image/webp;base64,"},{"id":20,"name":"Laurel","uses":"digestión, gases, resfríos.","part":"hojas.","how":"en comidas o decocción.","precaution":"no en embarazo en grandes cantidades.","substitute":"orégano.","sourcePage":32,"image":"./assets/plants/laurel.webp","imageData":"data:image/webp;base64,"},{"id":21,"name":"Limón (cáscara y jugo)","uses":"defensas, digestión, resfríos.","part":"jugo y cáscara.","how":"en infusiones, jarabes, tónicos.","precaution":"no abusar si hay gastritis fuerte.","substitute":"naranja.","sourcePage":33,"image":"./assets/plants/limon.webp","imageData":"data:image/webp;base64,"},{"id":22,"name":"Perejil","uses":"diurético suave, depurar, retención.","part":"hojas.","how":"en jugos o infusión.","precaution":"no embarazadas en grandes dosis.","substitute":"diente de león.","sourcePage":34,"image":"./assets/plants/perejil.webp","imageData":"data:image/webp;base64,"},{"id":23,"name":"Ajo","uses":"antibiótico natural, defensas, hongos.","part":"diente.","how":"crudo, macerado en aceite, jarabes.","precaution":"anticoagulados y gastritis: moderar.","substitute":"cebolla.","sourcePage":35,"image":"./assets/plants/ajo.webp","imageData":"data:image/webp;base64,"},{"id":24,"name":"Cebolla","uses":"tos, catarro, resfrío.","part":"bulbo.","how":"jarabes con miel, vapores, en la pieza.","precaution":"diabéticos controlen.","substitute":"ajo.","sourcePage":36,"image":"./assets/plants/cebolla.webp","imageData":"data:image/webp;base64,"},{"id":25,"name":"Malva","uses":"irritaciones de garganta, tos seca, piel.","part":"flores y hojas.","how":"infusión tibia y gárgaras.","precaution":"casi sin contraindicaciones.","substitute":"manzanilla.","sourcePage":37,"image":"./assets/plants/malva.webp","imageData":"data:image/webp;base64,"},{"id":26,"name":"Cola de caballo","uses":"diurético, articulaciones, uñas/pelo.","part":"tallos.","how":"decocción 10-15 min.","precaution":"no usar por tiempos muy largos.","substitute":"diente de león.","sourcePage":38,"image":"./assets/plants/cola-de-caballo.webp","imageData":"data:image/webp;base64,"},{"id":27,"name":"Pasiflora (mburucuyá)","uses":"ansiedad, insomnio, palpitaciones nerviosas.","part":"partes aéreas.","how":"infusión o tintura.","precaution":"no mezclar con sedantes sin consultar.","substitute":"tilo + lavanda.","sourcePage":39,"image":"./assets/plants/pasiflora.webp","imageData":"data:image/webp;base64,"},{"id":28,"name":"Valeriana","uses":"insomnio más marcado, nervios, tensión.","part":"raíz.","how":"decocción corta o tintura.","precaution":"puede dar somnolencia.","substitute":"pasiflora.","sourcePage":40,"image":"./assets/plants/valeriana.webp","imageData":"data:image/webp;base64,"},{"id":29,"name":"Rosa mosqueta","uses":"piel, cicatrización, envejecimiento, defensas.","part":"fruto (interno) y aceite.","how":"aceite en piel, infusión de frutos secos.","precaution":"casi ninguna, salvo alergias.","substitute":"caléndula + vitamina E.","sourcePage":41,"image":"./assets/plants/rosa-mosqueta.webp","imageData":"data:image/webp;base64,"},{"id":30,"name":"Saúco","uses":"estados gripales, fiebre baja, defensas.","part":"flores.","how":"infusión caliente con miel.","precaution":"no usar hojas ni frutos crudos.","substitute":"eucalipto + limón.","sourcePage":42,"image":"./assets/plants/sauco.webp","imageData":"data:image/webp;base64,"}],"preparations":[{"id":"infusion","title":"Infusión básica","icon":"🫖","bestFor":"Hojas, flores y partes blandas","ingredients":["1 cda de planta seca (o 2 cdas si es fresca)","200 ml de agua caliente, sin hervor prolongado","Miel o limón opcional"],"steps":["Calentá el agua hasta que casi hierva.","Colocá la planta en una taza o frasco.","Verté el agua encima y tapá.","Dejá reposar entre 5 y 10 minutos.","Colá y usá tibio."],"note":"Tapar ayuda a conservar los componentes aromáticos y volátiles."},{"id":"decoccion","title":"Decocción","icon":"♨️","bestFor":"Raíces, cortezas y semillas duras","ingredients":["1 cda de raíz, corteza o semilla dura","250 ml de agua","Endulzante opcional"],"steps":["Poné la planta y el agua en una olla.","Llevá a hervor suave.","Mantené entre 10 y 15 minutos.","Apagá y dejá reposar 5 minutos.","Colá y usá tibio."],"note":"Es la extracción indicada para partes vegetales duras."},{"id":"jarabe","title":"Jarabe herbal","icon":"🍯","bestFor":"Preparaciones concentradas y agradables de tomar","ingredients":["2 tazas de agua","2 cdas de mezcla de plantas","1 taza de miel o azúcar mascabo","Limón opcional"],"steps":["Prepará una infusión o decocción concentrada.","Colá y volvé a colocar el líquido en la olla.","Agregá el ingrediente dulce a fuego muy bajo.","Mezclá sin hervir la miel.","Envasá en un frasco esterilizado y refrigerá."],"note":"La miel no se utiliza en menores de 12 meses."},{"id":"oleato","title":"Macerado en aceite","icon":"🫙","bestFor":"Piel, masajes y bases de ungüentos","ingredients":["Planta completamente seca","Aceite vegetal","Frasco limpio y seco"],"steps":["Llená hasta dos tercios del frasco con la planta.","Cubrí totalmente con aceite.","Cerrá y etiquetá.","Macerá de 3 a 4 semanas en un lugar tibio y oscuro.","Agitá cada dos días, colá y envasá en oscuro."],"note":"La ausencia de humedad es esencial para evitar deterioro."},{"id":"tintura","title":"Tintura madre casera","icon":"💧","bestFor":"Extractos concentrados y de larga conservación","ingredients":["1 parte de planta seca o 2 de planta fresca","5 partes de alcohol apto","Frasco oscuro"],"steps":["Colocá la planta picada en el frasco.","Cubrí por completo con alcohol.","Cerrá y etiquetá.","Guardá 21 días en oscuridad y agitá a diario.","Colá y guardá en gotero oscuro."],"note":"No es una preparación apropiada para todas las personas; revisá cada planta y situación particular."},{"id":"unguento","title":"Ungüento o bálsamo","icon":"🧴","bestFor":"Uso externo, piel y masajes","ingredients":["100 ml de aceite macerado","15 a 20 g de cera de abejas","Aceites esenciales opcionales y correctamente diluidos"],"steps":["Derretí la cera a baño María.","Agregá el aceite macerado y mezclá.","Retirá del calor.","Cuando baje la temperatura, agregá los opcionales.","Envasá limpio y dejá solidificar."],"note":"Realizá una prueba de sensibilidad en una zona pequeña."}],"specialGuides":[],"safety":{"general":["Usá la aplicación para malestares leves o conocidos, no para diagnosticar.","Natural no significa inocuo: evitá mezclar plantas al azar.","No suspendas medicación indicada por profesionales.","Embarazo, lactancia, infancia y medicación crónica requieren consulta previa.","Probá productos tópicos en una zona pequeña antes de un uso más amplio."],"redFlags":["Fiebre alta o que persiste más de 48 horas","Dolor agudo, intenso o punzante","Sangrado","Dificultad para respirar","Vómitos persistentes o signos de deshidratación","Síntoma grave, nuevo o que empeora","Bebé menor de 6 meses con síntomas","Persona mayor con varias enfermedades o cuadro complejo"],"specialSituations":["Embarazo o lactancia","Niños y bebés","Anticoagulantes","Hipertensión","Diabetes","Tiroides","Tratamiento oncológico","Trasplante","Uso de sedantes o múltiples medicamentos"]},"categories":[{"name":"Inflamación y dolores","icon":"🦴","start":1,"end":35,"subcategories":[{"name":"Dolores articulares","start":1,"end":5},{"name":"Inflamación general","start":6,"end":10},{"name":"Dolores musculares","start":11,"end":15},{"name":"Cervicales","start":16,"end":20},{"name":"Rodillas","start":21,"end":25},{"name":"Manos rígidas","start":26,"end":30},{"name":"Dolores por frío y humedad","start":31,"end":35}]},{"name":"Digestión","icon":"🌿","start":36,"end":135,"subcategories":[{"name":"Gases","start":36,"end":45},{"name":"Hinchazón abdominal","start":46,"end":55},{"name":"Digestión pesada","start":56,"end":65},{"name":"Empacho","start":66,"end":75},{"name":"Acidez","start":76,"end":85},{"name":"Estreñimiento","start":86,"end":95},{"name":"Hígado cargado","start":96,"end":105},{"name":"Vesícula perezosa","start":106,"end":115},{"name":"Colon irritable","start":116,"end":125},{"name":"Náuseas","start":126,"end":135}]},{"name":"Ansiedad y sueño","icon":"🌙","start":136,"end":165,"subcategories":[{"name":"Insomnio","start":136,"end":140},{"name":"Ansiedad","start":141,"end":145},{"name":"Estrés","start":146,"end":150},{"name":"Nervios","start":151,"end":155},{"name":"Pensamientos acelerados","start":156,"end":160},{"name":"Palpitaciones por nervios","start":161,"end":165}]},{"name":"Defensas y resfríos","icon":"🫁","start":166,"end":225,"subcategories":[{"name":"Gripes y resfríos","start":166,"end":175},{"name":"Tos seca y con flema","start":176,"end":185},{"name":"Garganta irritada","start":186,"end":195},{"name":"Defensas bajas","start":196,"end":205},{"name":"Congestión nasal","start":206,"end":215},{"name":"Bronquios cargados","start":216,"end":225}]},{"name":"Metabolismo y peso","icon":"⚖️","start":226,"end":260,"subcategories":[{"name":"Control de peso","start":226,"end":230},{"name":"Retención de líquidos","start":231,"end":235},{"name":"Colesterol","start":236,"end":240},{"name":"Azúcar en sangre","start":241,"end":245},{"name":"Metabolismo lento","start":246,"end":250},{"name":"Celulitis","start":251,"end":255},{"name":"Hígado graso","start":256,"end":260}]},{"name":"Dolor articular y huesos","icon":"🦵","start":261,"end":295,"subcategories":[{"name":"Artritis leve","start":261,"end":265},{"name":"Artrosis","start":266,"end":270},{"name":"Dolores por frío","start":271,"end":275},{"name":"Rigidez matinal","start":276,"end":280},{"name":"Menopausia y sofocos","start":281,"end":285},{"name":"Remineralización","start":286,"end":290},{"name":"Circulación","start":291,"end":295}]},{"name":"Piel y circulación","icon":"✨","start":296,"end":330,"subcategories":[{"name":"Piel seca o irritada","start":296,"end":300},{"name":"Manos resecas","start":301,"end":305},{"name":"Cabello y caída","start":306,"end":310},{"name":"Manchas en piel","start":311,"end":315},{"name":"Piernas pesadas","start":316,"end":320},{"name":"Várices leves","start":321,"end":325},{"name":"Celulitis","start":326,"end":330}]}],"bonuses":[{"id":"urgencias","title":"Botiquín Natural de Urgencias","icon":"🧰","type":"Autocuidado cotidiano","summary":"Un kit doméstico y diez recetas express para molestias leves del día real.","warning":"No corresponde ante fiebre alta persistente, dificultad para respirar, alergia importante, dolor intenso o empeoramiento.","sections":[{"id":"armar","title":"Armá tu botiquín","icon":"🧺","description":"Ingredientes, materiales y preparados base.","items":[{"id":"urg-kit-base","title":"Qué debe tener siempre tu kit","kind":"guide","summary":"Base doméstica accesible para resolver preparaciones simples en pocos minutos.","benefits":["Jengibre: resfrío que empieza, garganta rara, náuseas y digestión lenta.","Manzanilla: digestivo, cólico leve, nervios y compresas.","Lavanda: calma, sueño y dolor de cabeza tensional.","Menta o hierbabuena: pesadez, congestión y náuseas.","Cúrcuma: inflamación, articulaciones y garganta.","Miel, limón, sal, vinagre, aceite neutro y alcohol apto completan la base."],"notes":["Opcionales: propóleo, eucalipto, árbol de té y romero."]},{"id":"urg-kit-organizacion","title":"Cómo organizar el botiquín","kind":"guide","summary":"Separá lo que se usa por vía interna, externa y en niños.","steps":["Usá una caja con tapa o un cajón exclusivo.","Guardá cuatro frascos chicos con etiquetas, un gotero, un roll-on, colador, cuchara medidora y tijera limpia.","Rotulá sectores: INTERNOS, EXTERNOS y NIÑOS.","En cada preparado indicá nombre, fecha y conservación."]},{"id":"urg-kit-listos","title":"Tres preparados para tener listos","kind":"guide","summary":"Formatos que reducen el tiempo de respuesta.","ingredients":["Polvos secos: manzanilla, menta, jengibre seco y cúrcuma.","Aceite rápido de calma: 2 cdas de aceite neutro + 1 cda de lavanda seca + 1 cda de manzanilla seca.","Miel medicinal base: 4 cdas de miel + 1 cdita de cúrcuma + 1 cdita de jengibre en polvo + 1 cdita de limón."],"conservation":["Polvos secos: 6 a 12 meses, lejos de calor y sol.","Aceite de calma: 30 días.","Miel medicinal base: 15 días en heladera."]}]},{"id":"resfrio","title":"Resfrío y garganta","icon":"🫁","description":"Preparaciones rápidas para inicio de resfrío, garganta y tos.","items":[{"id":"urg-1","title":"Miel dorada express para garganta que arde","kind":"recipe","summary":"Para ardor e irritación leve de garganta.","ingredients":["1 cda de miel pura","1/4 cdita de cúrcuma","1/4 cdita de jengibre en polvo","1 chorrito de limón"],"steps":["Poné la miel en una tacita.","Sumá cúrcuma y jengibre y mezclá.","Agregá el limón al final."],"use":["Tomar de a cucharaditas cada 2 a 3 horas."],"benefits":["Calma el ardor.","Apoyo antimicrobiano suave.","Ayuda a bajar la inflamación local."],"warnings":["La miel no se usa en menores de 12 meses.","Si hay tos seca, el material propone una pizca de sal."]},{"id":"urg-4","title":"Infusión para comienzo de resfrío","kind":"recipe","summary":"Para sensación de frío interno al inicio de un cuadro leve.","ingredients":["1 rodaja de jengibre fresco o 1/2 cdita en polvo","1 cdita de miel","1 cdita de limón","200 ml de agua caliente"],"steps":["Infusioná el jengibre 5 minutos.","Colá y agregá miel y limón."],"use":["Tomar caliente y abrigarse. El material propone repetir hasta 3 veces durante el primer día."],"benefits":["Aporta sensación de calor.","Acompaña la circulación y el inicio de un resfrío leve."],"warnings":["La miel no se usa en menores de 12 meses."]},{"id":"urg-8","title":"Gárgaras para garganta irritada y voz gastada","kind":"recipe","summary":"Uso externo: hacer gárgaras y escupir.","ingredients":["200 ml de agua tibia","1 cdita de sal","1 cdita de vinagre de manzana"],"steps":["Mezclá los ingredientes.","Hacé gárgaras durante 30 segundos.","Escupí."],"use":["Repetir 3 a 4 veces durante el día."],"benefits":["Acompaña la irritación leve.","Ayuda a aflojar mucosidad."]},{"id":"urg-9","title":"Miel para crisis de tos nocturna leve","kind":"recipe","summary":"Preparación para dejar resbalar lentamente por la garganta.","ingredients":["1 cda de miel","1 pizca de cúrcuma","1 pizca de jengibre","1 gota de limón"],"steps":["Mezclá todo.","Tomá 1 cdita y dejá que resbale por la garganta.","No comas ni bebas durante 15 minutos."],"benefits":["Calma el reflejo de tos.","Lubrica la garganta."],"warnings":["Solo para mayores de 1 año."]}]},{"id":"panza","title":"Panza y náuseas","icon":"🌿","description":"Infusiones para molestias digestivas leves.","items":[{"id":"urg-3","title":"Infusión para digestión pesada","kind":"recipe","summary":"Para pesadez y gases después de una comida.","ingredients":["1 cdita de manzanilla","1 cdita de menta","200 ml de agua caliente","1 rodajita de limón"],"steps":["Verté agua caliente sobre las hierbas.","Tapá y dejá 5 minutos.","Colá y agregá el limón."],"use":["Tomar tibio, a sorbitos."],"benefits":["Ayuda a bajar gases.","Acompaña la digestión pesada."]},{"id":"urg-5","title":"Infusión para panza revuelta o náusea leve","kind":"recipe","summary":"Para náusea leve o nervios en la panza.","ingredients":["1 cdita de menta","1 cdita de manzanilla","200 ml de agua","1 cdita de miel, opcional"],"steps":["Hacé una infusión de 5 minutos.","Colá."],"use":["Tomar tibio. Para niños, el material propone solo manzanilla y media cantidad."],"benefits":["Calma náusea leve.","Relaja el estómago."]},{"id":"urg-10","title":"Infusión comodín “me siento rara”","kind":"recipe","summary":"Para cansancio leve acompañado de cabeza cargada y panza sensible.","ingredients":["1 cdita de manzanilla","1 cdita de menta","1 rodajita de jengibre","1 cdita de miel","200 ml de agua caliente"],"steps":["Infusioná todo junto 5 minutos.","Colá.","Endulzá y tomá despacio."],"benefits":["Acompaña la digestión.","Refresca la cabeza.","El material la propone al inicio de un cuadro viral leve."]}]},{"id":"dolores","title":"Dolores y contracturas","icon":"🦴","description":"Aplicaciones externas para tensión leve.","items":[{"id":"urg-2","title":"Aceite para dolor de cabeza por tensión","kind":"recipe","summary":"Aplicación externa para sienes, nuca y detrás de las orejas.","ingredients":["1 cdita de aceite de oliva","2 gotas de lavanda o 1 cdita de lavanda seca humedecida","1 cdita de menta triturada o 1 gota de aceite de menta"],"steps":["Mezclá todo en un platito.","Frotá una pequeña cantidad entre los dedos.","Aplicá en sienes, nuca y detrás de las orejas.","Respirá profundo durante un minuto."],"benefits":["Descongestiona.","Relaja.","Pensado para cefalea tensional."],"warnings":["No tocar los ojos.","No usar aceite esencial puro en niños."]},{"id":"urg-6","title":"Aceite para dolor muscular o cuello duro","kind":"recipe","summary":"Masaje externo para tensión muscular leve.","ingredients":["2 cdas de aceite neutro","1 cdita de romero o menta seca","1 cdita de lavanda"],"steps":["Mezclá y entibiá apenas entre las manos.","Masajeá la zona 3 a 5 minutos.","Tapá con un paño tibio."],"benefits":["Activa la circulación local.","Ayuda a relajar."],"warnings":["Si el dolor es por un golpe, el material indica no aplicar calor."]}]},{"id":"calma","title":"Estrés y sueño","icon":"🌙","description":"Una preparación para bajar el ritmo.","items":[{"id":"urg-7","title":"Infusión para ansiedad o mente acelerada","kind":"recipe","summary":"Ritual breve para bajar el ritmo.","ingredients":["1 cdita de lavanda","1 cdita de manzanilla","200 ml de agua caliente","1 cdita de miel"],"steps":["Infusioná 5 a 7 minutos.","Colá.","Tomá despacio inhalando el vapor.","Descansá 10 minutos sin celular."],"benefits":["Ayuda a bajar el ritmo.","Puede acompañar el descanso nocturno."]}]},{"id":"seguridad","title":"Cuándo consultar","icon":"🛡️","description":"Límites del botiquín casero.","items":[{"id":"urg-alertas","title":"Alertas de seguridad","kind":"guide","summary":"El material indica consulta ante fiebre alta que no baja, dificultad para respirar o alergia en piel.","warnings":["Cúrcuma: moderar si hay cálculos biliares sin control.","Miel: no usar en menores de 1 año.","Embarazo: evitar mezclas estimulantes con exceso de menta, romero o salvia."]}]}]},{"id":"infantil","title":"Botiquín Natural Infantil","icon":"🧸","type":"Guía con límites por edad","summary":"Preparaciones y recursos ambientales organizados por edad para molestias leves infantiles.","warning":"No reemplaza la consulta pediátrica. Ante duda, empeoramiento o señales de alarma, consultá.","ageSelector":true,"sections":[{"id":"edad","title":"Reglas por edad","icon":"🧒","description":"Antes de elegir una preparación, revisá la edad.","items":[{"id":"inf-reglas","title":"Reglas rápidas por edad","kind":"guide","summary":"La edad define qué recursos pueden usarse.","benefits":["Menores de 6 meses: sin aceites esenciales, sin miel y sin vapor directo.","Miel únicamente a partir de los 12 meses.","Vapor o baño caliente: siempre con una persona adulta y durante 5 a 10 minutos.","No usar preparados caseros sobre heridas abiertas."],"warnings":["Fiebre en menores de 3 meses, silbidos, pecho que se hunde, labios azulados o somnolencia llamativa requieren atención inmediata."]}]},{"id":"tos","title":"Tos y congestión","icon":"🫁","description":"Recursos para tos leve, moco y descanso.","items":[{"id":"inf-jarabe-miel","title":"Jarabe de miel, limón y jengibre","kind":"recipe","summary":"Para tos nocturna leve o garganta irritada.","ingredients":["4 cdas de miel pura","2 cdas de jugo de limón","2 rodajas finas de jengibre","40 ml de agua caliente"],"steps":["Tibiá el agua.","Cubrí el jengibre con el agua durante 5 minutos.","Colá y dejá bajar la temperatura.","Agregá miel y limón.","Guardá en frasco limpio."],"use":["1 a 3 años: 1/2 cdita, 3 veces al día.","4 a 6 años: 1 cdita, 3 veces al día.","7 años o más: 1 cda, 3 veces al día."],"benefits":["La miel alivia la tos nocturna.","El jengibre acompaña la garganta."],"conservation":["Hasta 3 días en heladera."],"warnings":["No usar en menores de 1 año ni ante alergia."],"minAgeMonths":12},{"id":"inf-cebolla","title":"Jarabe de cebolla dulce","kind":"recipe","summary":"Opción sin miel para catarro, moco claro o tos suave.","ingredients":["1 cebolla blanca chica","2 cdas de azúcar mascabo o azúcar común","40 ml de agua"],"steps":["Picá la cebolla muy pequeña.","Ponela en un frasco limpio y cubrí con azúcar.","Dejá entre 4 y 6 horas hasta que suelte almíbar.","Colá."],"use":["1/2 cdita cada 6 a 8 horas, máximo 3 veces al día."],"benefits":["La cebolla se presenta como expectorante suave."],"conservation":["24 horas en heladera."],"minAgeMonths":8},{"id":"inf-vapor","title":"Vapor de baño seguro","kind":"recipe","summary":"Recurso ambiental para nariz tapada o tos con moco.","ingredients":["Baño","Agua caliente de la ducha","Toallita"],"steps":["Cerrá puertas y ventanas.","Dejá correr la ducha caliente 5 a 7 minutos para generar vapor.","Entrá con el niño sin colocarlo debajo de la ducha y permanecé 5 minutos.","Limpiá la nariz con suavidad."],"benefits":["Ayuda a fluidificar el moco.","No utiliza aceites esenciales en el ambiente del bebé."],"minAgeMonths":0},{"id":"inf-unguento","title":"Ungüento respiratorio suave","kind":"recipe","summary":"Masaje externo para pecho y espalda.","ingredients":["2 cdas de aceite de coco o almendra","1 cdita de cera de abeja","1 gota de aceite esencial de lavanda","1 gota de aceite esencial de manzanilla"],"steps":["Derretí aceite y cera a baño María.","Retirá y dejá entibiar.","Agregá las dos gotas.","Guardá en un pote pequeño."],"use":["Frotar pecho y espalda antes de dormir. No aplicar en cara ni nariz."],"warnings":["Solo para mayores de 2 años.","No usar en personas asmáticas sin aval pediátrico."],"minAgeMonths":24}]},{"id":"piel","title":"Piel y rozaduras","icon":"🧴","description":"Preparaciones externas para piel íntegra.","items":[{"id":"inf-avena","title":"Cremita de avena y caléndula","kind":"recipe","summary":"Para pañalitis leve y piel íntegra.","ingredients":["2 cdas de avena molida","2 cdas de aceite de coco","1 cda de infusión fría de caléndula"],"steps":["Prepará una infusión cargada de caléndula y dejala enfriar.","Mezclá avena y aceite de coco.","Agregá la infusión hasta formar una pasta."],"use":["Con la zona seca, aplicar una capa fina.","Dejar 10 a 15 minutos al aire.","Luego puede colocarse la crema habitual."],"benefits":["La caléndula calma.","La avena acompaña el enrojecimiento."],"warnings":["No usar si la piel está partida o tiene pus."]},{"id":"inf-spray","title":"Spray calmante de manzanilla","kind":"recipe","summary":"Para pequeños brotes o irritación leve.","ingredients":["100 ml de infusión cargada de manzanilla, fría","1 cdita de aceite de almendras","Frasco con spray"],"steps":["Prepará la infusión y dejala enfriar por completo.","Pasala al spray y agregá el aceite.","Agitá antes de cada uso."],"use":["Rociar 2 a 3 veces al día y secar con golpecitos."],"conservation":["Preparar poca cantidad y conservar refrigerado."]}]},{"id":"panza","title":"Panza y digestión","icon":"🌿","description":"Apoyo para gases y cólicos.","items":[{"id":"inf-hinojo","title":"Agüita de hinojo y anís","kind":"recipe","summary":"Para cólicos y gases.","ingredients":["1/2 cdita de semillas de hinojo","1/2 cdita de semillas de anís","200 ml de agua"],"steps":["Herví el agua.","Agregá las semillas, tapá y dejá 10 minutos.","Colá muy bien."],"use":["6 a 12 meses: 1 a 2 cucharaditas tibias después de comer.","1 a 3 años: 20 a 30 ml tibios."],"warnings":["Vómitos, sangre en materia fecal o dolor que despierta requieren consulta."],"minAgeMonths":6}]},{"id":"confort","title":"Fiebre y confort","icon":"🌡️","description":"Medida de confort con límites claros.","items":[{"id":"inf-compresa","title":"Compresa tibia de confort","kind":"recipe","summary":"Medida de confort ante fiebre; no reemplaza antitérmicos indicados.","ingredients":["Bowl con agua tibia","2 gotas de vinagre de manzana","Toallita de algodón"],"steps":["Mezclá agua y vinagre.","Mojá y escurrí la toallita.","Colocá en frente, nuca o plantas de los pies.","Cambiá cada 5 a 7 minutos."],"warnings":["Fiebre en menores de 3 meses, por más de 48 horas o con decaimiento y respiración rápida requiere atención."]}]},{"id":"botiquin","title":"Lista del botiquín infantil","icon":"🧺","description":"Elementos sugeridos por el material.","items":[{"id":"inf-lista","title":"Ingredientes y materiales","kind":"guide","summary":"Prepará un sector separado y rotulado.","ingredients":["Miel pura para mayores de 1 año","Limón, jengibre y cebolla","Manzanilla y caléndula secas","Aceite de coco y avena molida","Semillas de hinojo y anís","Frascos chicos, spray vacío, termómetro y humidificador opcional"]}]},{"id":"alarmas","title":"Señales de alarma","icon":"🚨","description":"Casos en los que el botiquín natural no corresponde.","items":[{"id":"inf-alarmas","title":"Cuándo llamar o ir a guardia","kind":"guide","summary":"El material indica atención inmediata en los siguientes casos.","warnings":["Bebé menor de 3 meses con 38 °C o más.","Labios o uñas azulados.","Respiración rápida o pecho que se hunde.","Llanto extraño o somnolencia llamativa.","Fiebre que no baja con manchas en la piel.","Vómitos persistentes."]}]}]},{"id":"preparaciones","title":"Guía Maestra de Preparaciones Ancestrales","icon":"⚗️","type":"Taller práctico","summary":"Métodos base, higiene y fórmulas modelo para jarabes, tinturas, ungüentos, oleatos y cremas.","warning":"Las preparaciones son educativas y de apoyo. Revisá siempre la planta, la vía de uso y las situaciones especiales.","sections":[{"id":"metodos","title":"Métodos base","icon":"📐","description":"Proporciones, higiene y pasos comunes.","items":[{"id":"prep-higiene","title":"Higiene y materiales","kind":"guide","summary":"Reglas comunes para preparados domésticos.","steps":["Usá agua potable segura.","Elegí plantas limpias, sin hongos ni humedad extraña.","Lavá, enjuagá y escaldá los frascos; dejalos secar boca abajo.","No introduzcas cucharas húmedas o usadas.","Etiquetá nombre, plantas, fecha y conservación."],"warnings":["Moho, burbujas, olor extraño o tapa hinchada: descartar."]},{"id":"prep-metodo-jarabe","title":"Método base de jarabes","kind":"method","summary":"Para extractos acuosos concentrados con una fase dulce.","steps":["Elegí plantas según el objetivo.","Prepará una infusión o decocción y colá muy bien.","Dejá entibiar por debajo de 40 °C.","Agregá una cantidad de miel o azúcar equivalente al líquido y mezclá.","Envasá limpio, etiquetá y refrigerá."],"warnings":["Miel: no usar en menores de 1 año.","Diabetes o resistencia a la insulina: consultar."]},{"id":"prep-metodo-tintura","title":"Método base de tinturas","kind":"method","summary":"Extractos concentrados en solvente hidroalcohólico.","steps":["Usá una parte de planta seca por cinco partes de alcohol apto.","Cubrí totalmente la planta.","Macerá 21 a 30 días en oscuridad y agitá a diario.","Filtrá y guardá en gotero oscuro."],"warnings":["No es una preparación apropiada para todas las personas.","No combinar con medicación sin revisar la planta y la situación."]},{"id":"prep-metodo-unguento","title":"Método base de ungüentos","kind":"method","summary":"Preparación tópica con oleato y cera.","steps":["Calentá el oleato a baño María.","Agregá la cera y fundí suavemente.","Retirá del calor.","Agregá opcionales cuando baje la temperatura.","Envasá limpio y dejá enfriar sin tapa."],"warnings":["Uso externo.","Realizar prueba de sensibilidad."]},{"id":"prep-metodo-oleato","title":"Método base de oleatos","kind":"method","summary":"Maceración de plantas en aceite para masajes y bases cosméticas.","steps":["Usá planta bien seca.","Cubrí completamente con aceite.","Macerá 3 a 4 semanas en lugar tibio y oscuro.","Agitá con frecuencia.","Colá, exprimí y guardá en frasco seco y oscuro."],"conservation":["Entre 6 y 12 meses, según aceite y conservación."]},{"id":"prep-metodo-crema","title":"Método base de cremas","kind":"method","summary":"Emulsión de una fase oleosa y una fase acuosa.","steps":["Fundí oleato y cera a baño María.","Calentá aparte la infusión o el agua.","Retirá la fase oleosa del fuego.","Agregá la fase acuosa de a poco mientras batís.","Continuá hasta lograr textura cremosa.","Envasá limpio y refrigerá."],"warnings":["Todo preparado con agua dura menos y requiere mayor higiene."]}]},{"id":"jarabes","title":"Jarabes","icon":"🍯","description":"Diez fórmulas modelo del material.","items":[{"id":"jar-miel-jengibre","title":"Jarabe de miel, limón y jengibre","kind":"recipe","summary":"Para resfrío leve inicial, garganta áspera y sensación de frío.","ingredients":["250 ml de agua","25 a 30 g de jengibre fresco","Cáscara de 1/2 limón","Jugo de 1 limón","220 a 250 g de miel"],"steps":["Herví suavemente agua, jengibre y cáscara 8 a 10 minutos.","Apagá y reposá tapado 10 minutos.","Colá.","Cuando esté tibio, agregá miel y jugo de limón.","Envasá y refrigerá."],"use":["Adultos: 1 cda cada 3 a 4 horas en fase inicial leve; como apoyo, 1 a 2 cdas al día."],"warnings":["No menores de 1 año.","Gastritis sensible: reducir jengibre."]},{"id":"jar-tomillo-malva","title":"Jarabe de tomillo y malva","kind":"recipe","summary":"Para tos irritativa leve, garganta raspada y mucosa sensible.","ingredients":["300 ml de agua","10 g de tomillo seco","10 g de malva o malvavisco","250 a 300 g de miel"],"steps":["Herví el tomillo 5 minutos.","Apagá, agregá la malva y reposá tapado 10 a 15 minutos.","Colá, entibiá y agregá miel."],"use":["Adultos: 1 cda cada 3 a 4 horas."],"warnings":["Tos con sangre, silbidos, falta de aire o fiebre alta requieren atención."]},{"id":"jar-digestivo","title":"Jarabe digestivo de manzanilla, menta e hinojo","kind":"recipe","summary":"Para gases, digestión lenta y pesadez post comida.","ingredients":["250 ml de agua","5 g de manzanilla","5 g de menta","5 g de hinojo machacado","200 a 250 g de miel o azúcar mascabo"],"steps":["Herví el hinojo 5 minutos.","Apagá y agregá manzanilla y menta.","Reposá tapado 10 a 12 minutos.","Colá, entibiá y agregá la fase dulce."],"use":["1 cda después de comidas pesadas o ante molestia leve."],"warnings":["Dolor fuerte, fiebre o vómitos: no manejar con jarabe."]},{"id":"jar-noche","title":"Jarabe calmante nocturno","kind":"recipe","summary":"Para nervios leves y dificultad para bajar el ritmo.","ingredients":["250 ml de agua","5 g de tilo","5 g de manzanilla","3 a 5 g de azahar, opcional","200 a 250 g de miel"],"steps":["Calentá el agua sin hervor fuerte.","Agregá las flores y reposá tapado 10 a 15 minutos.","Colá, entibiá y agregá miel."],"use":["Adultos: 1 cda 30 a 40 minutos antes de dormir."],"warnings":["No combinar con medicación sedante sin consultar."]},{"id":"jar-tonico","title":"Jarabe tónico suave de limón, romero y jengibre","kind":"recipe","summary":"Para cansancio leve y necesidad de foco sin estimulantes fuertes.","ingredients":["300 ml de agua","5 g de romero","10 g de jengibre","Jugo de 1 limón","250 a 300 g de miel"],"steps":["Herví agua, jengibre y romero 5 a 7 minutos.","Reposá 10 minutos y colá.","Entibiá, agregá miel y jugo de limón."],"use":["Adultos: 1 cda por la mañana."],"warnings":["No recomendado en embarazo sin supervisión.","Hipertensión descompensada: consultar."]},{"id":"jar-cebolla","title":"Jarabe respiratorio de cebolla, miel y limón","kind":"recipe","summary":"Para tos leve, congestión suave y garganta irritada.","ingredients":["1 cebolla mediana en rodajas","200 a 250 g de miel","Jugo de 1/2 limón","1 a 2 rodajas de jengibre, opcional"],"steps":["Colocá cebolla y jengibre en un frasco limpio.","Cubrí con miel.","Macerá 8 a 12 horas.","Colá y agregá limón."],"conservation":["Consumir en 5 a 7 días, refrigerado."],"warnings":["No menores de 1 año."]},{"id":"jar-curcuma","title":"Jarabe suave de cúrcuma y jengibre","kind":"recipe","summary":"Apoyo en inflamación leve y rigidez matinal ligera.","ingredients":["300 ml de agua","10 g de jengibre","8 g de cúrcuma fresca o 4 g en polvo","1 pizca de pimienta negra","250 a 280 g de miel"],"steps":["Herví agua, jengibre y cúrcuma 8 a 10 minutos.","Reposá tapado y colá.","Agregá pimienta y, cuando esté tibio, miel."],"use":["Adultos: 1 cda 1 a 2 veces al día con comida."],"warnings":["Precaución con anticoagulantes y problemas de vesícula."]},{"id":"jar-sauco","title":"Jarabe de saúco y limón","kind":"recipe","summary":"Apoyo suave en época de frío y cambios de clima.","ingredients":["300 ml de agua","10 g de flores o bayas secas de saúco","5 g de jengibre","Cáscara de 1/2 limón","220 a 260 g de miel"],"steps":["Herví suavemente 8 a 10 minutos.","Reposá tapado 10 a 15 minutos.","Colá y agregá miel cuando esté tibio."],"use":["Adultos: 1 cda 1 a 2 veces al día; al inicio de molestias leves, cada 3 a 4 horas."],"warnings":["Usar saúco correctamente identificado y bien seco."]},{"id":"jar-piernas","title":"Jarabe de romero, cola de caballo y limón","kind":"recipe","summary":"Para sensación de piernas pesadas y retención leve.","ingredients":["300 ml de agua","5 g de romero","5 g de cola de caballo","5 g de menta","Jugo de 1/2 limón","220 a 250 g de miel"],"steps":["Herví romero y cola de caballo 8 minutos.","Apagá, agregá menta y reposá 8 a 10 minutos.","Colá, entibiá, agregá miel y limón."],"use":["Adultos: 1 cda 1 a 2 veces al día."],"warnings":["No usar cola de caballo por más de 2 a 3 semanas sin supervisión.","No usar en embarazo."]},{"id":"jar-femenino","title":"Jarabe de equilibrio femenino suave","kind":"recipe","summary":"Para tensión premenstrual y cambios emocionales leves.","ingredients":["250 ml de agua","5 g de manzanilla","5 g de melisa","3 g de lavanda, opcional","200 a 230 g de miel"],"steps":["Calentá el agua y apagá.","Agregá hierbas y reposá tapado 10 a 12 minutos.","Colá y agregá miel cuando esté tibio."],"use":["Adultos: 1 cda 1 a 3 veces al día durante días de tensión."],"warnings":["Dolor muy intenso, ciclos muy irregulares o sangrado anormal requieren consulta."]}]},{"id":"tinturas","title":"Tinturas","icon":"💧","description":"Extractos concentrados para personas adultas.","items":[{"id":"tin-digestiva","title":"Tintura digestiva suave","kind":"recipe","summary":"Para gases, digestión lenta y pesadez leve.","ingredients":["10 g de manzanilla seca","10 g de menta seca","5 g de hinojo seco","125 ml de alcohol de 40 a 45 %"],"steps":["Macerá la mezcla 21 días.","Agitá a diario.","Filtrá."],"use":["Adultos: 15 a 20 gotas en agua después de comidas pesadas."],"warnings":["Dolor agudo intenso: consultar."]},{"id":"tin-calma","title":"Tintura calma y sueño suave","kind":"recipe","summary":"Para nervios leves y dificultad para bajar el ritmo.","ingredients":["10 g de tilo","10 g de melisa","5 g de pasiflora","125 ml de alcohol de 40 a 45 %"],"steps":["Macerá 21 a 30 días.","Filtrá y guardá en gotero oscuro."],"use":["Adultos: 20 gotas en agua 30 a 40 minutos antes de dormir."],"warnings":["No combinar con medicación sedante."]},{"id":"tin-defensas","title":"Tintura de defensas suaves","kind":"recipe","summary":"Apoyo durante épocas frías.","ingredients":["10 g de equinácea, opcional","10 g de saúco","5 g de jengibre","125 ml de alcohol de 45 %"],"steps":["Macerá 21 días.","Filtrá."],"use":["Adultos: 20 gotas 1 a 2 veces al día."],"warnings":["En diagnóstico autoinmune, consultar antes de usar equinácea."]},{"id":"tin-articular","title":"Tintura articular y circulatoria","kind":"recipe","summary":"Apoyo para rigidez y circulación leve.","ingredients":["10 g de romero","10 g de cúrcuma","5 g de jengibre","125 ml de alcohol de 45 a 50 %"],"steps":["Macerá 21 a 30 días.","Filtrá."],"use":["Adultos: 15 a 20 gotas 1 a 2 veces al día con comida."],"warnings":["No en embarazo. Precaución con anticoagulantes."]},{"id":"tin-higado","title":"Tintura digestiva de diente de león y boldo","kind":"recipe","summary":"Para pesadez posterior a comidas grasas.","ingredients":["15 g de diente de león","5 g de boldo","5 g de menta","125 ml de alcohol de 40 a 45 %"],"steps":["Macerá 21 días.","Filtrá."],"use":["Adultos: 15 a 20 gotas antes o después de comidas pesadas."],"warnings":["No usar en embarazo ni en obstrucción biliar sin control."]}]},{"id":"unguentos","title":"Ungüentos","icon":"🧴","description":"Preparaciones tópicas sin fase acuosa.","items":[{"id":"ung-muscular","title":"Ungüento muscular de romero y árnica","kind":"recipe","summary":"Para contracturas leves y golpes pequeños sin herida.","ingredients":["30 g de oleato de romero","20 g de oleato de árnica","12 a 15 g de cera de abejas","3 a 5 gotas de aceite esencial de romero o lavanda, opcional"],"steps":["Fundí oleatos y cera a baño María.","Retirá, dejá bajar la temperatura y agregá opcionales.","Envasá y dejá enfriar."],"use":["Aplicar poca cantidad 2 a 3 veces al día."],"warnings":["Árnica solo sobre piel intacta."]},{"id":"ung-manos","title":"Ungüento regenerador de caléndula y manzanilla","kind":"recipe","summary":"Para manos, codos, talones y zonas resecas.","ingredients":["40 g de oleato de caléndula","10 g de oleato de manzanilla","10 g de cera de abejas","2 a 3 gotas de lavanda, opcional"],"steps":["Seguí el método base de ungüento."],"use":["Aplicar 2 a 4 veces al día."],"warnings":["Alergia a asteráceas: realizar prueba previa."]},{"id":"ung-respiratorio","title":"Ungüento respiratorio de eucalipto y tomillo","kind":"recipe","summary":"Masaje externo para pecho y espalda en cuadros leves.","ingredients":["40 g de oleato de eucalipto y tomillo","12 a 15 g de cera","2 a 3 gotas de eucalipto radiata para adultos","1 a 2 gotas de menta, opcional para adultos"],"steps":["Seguí el método base y agregá aceites esenciales al final."],"use":["Masajear pecho y espalda 2 a 3 veces al día."],"warnings":["No aplicar eucalipto o menta cerca de nariz y boca en menores de 6 años."]},{"id":"ung-piernas","title":"Ungüento para piernas cansadas","kind":"recipe","summary":"Para pesadez leve después de permanecer mucho tiempo de pie.","ingredients":["30 g de oleato de castaño de Indias","20 g de oleato de romero","10 a 12 g de cera","3 gotas de menta, opcional"],"steps":["Seguí el método base."],"use":["Masajear de tobillos hacia rodillas 1 a 2 veces al día."],"warnings":["No usar sobre úlceras, flebitis o várices muy marcadas."]},{"id":"ung-noche","title":"Ungüento calmante nocturno","kind":"recipe","summary":"Ritual externo para nuca, muñecas, pecho alto o pies.","ingredients":["35 g de oleato de lavanda","15 g de oleato de manzanilla","10 g de cera","3 a 5 gotas de lavanda"],"steps":["Seguí el método base."],"use":["Aplicar antes de dormir."],"warnings":["El insomnio persistente requiere evaluación."]}]},{"id":"oleatos","title":"Oleatos","icon":"🫙","description":"Macerados en aceite para masaje y bases.","items":[{"id":"ole-calendula","title":"Oleato de caléndula","kind":"recipe","summary":"Base para piel sensible, reseca o irritada leve.","ingredients":["20 g de flores secas de caléndula","100 a 120 ml de aceite de oliva o girasol alto oleico"],"steps":["Macerá 3 a 4 semanas o usá baño María suave.","Colá y guardá en oscuro."],"use":["Aplicar sobre piel limpia 1 a 3 veces por día."],"warnings":["Alergia a asteráceas: prueba previa."]},{"id":"ole-lavanda","title":"Oleato de lavanda","kind":"recipe","summary":"Para masajes relajantes y ritual nocturno.","ingredients":["20 g de flores secas de lavanda","100 ml de aceite de almendras o girasol"],"steps":["Aplicá el método base."],"use":["Masajear nuca, hombros o plantas de los pies."]},{"id":"ole-romero","title":"Oleato de romero","kind":"recipe","summary":"Para masaje en piernas, cuero cabelludo y tensión leve.","ingredients":["20 g de romero seco","100 a 120 ml de aceite de oliva o girasol"],"steps":["Aplicá el método base."],"use":["Masaje ascendente en piernas.","Fricción suave en cuero cabelludo antes del lavado."],"warnings":["No usar de forma amplia en embarazo avanzado ni con hipertensión descompensada sin orientación."]},{"id":"ole-respiratorio","title":"Oleato respiratorio de eucalipto y tomillo","kind":"recipe","summary":"Para masaje externo en pecho y espalda.","ingredients":["10 g de eucalipto seco","10 g de tomillo seco","120 ml de aceite"],"steps":["Aplicá el método base."],"use":["Masajear pecho y espalda sin acercar a fosas nasales."],"warnings":["Dificultad respiratoria: consulta urgente."]},{"id":"ole-capilar","title":"Oleato capilar de romero y ortiga","kind":"recipe","summary":"Para masaje previo al lavado.","ingredients":["10 g de romero seco","10 g de ortiga seca","120 ml de aceite"],"steps":["Aplicá el método base."],"use":["Masajear el cuero cabelludo 20 a 30 minutos antes del lavado, 2 a 3 veces por semana."],"warnings":["Caída intensa o placas requieren evaluación."]}]},{"id":"cremas","title":"Cremas","icon":"✨","description":"Emulsiones de fase oleosa y acuosa.","items":[{"id":"cre-piel","title":"Crema calmante de caléndula y manzanilla","kind":"recipe","summary":"Para piel sensible y enrojecimiento leve.","ingredients":["25 g de oleato de caléndula","5 a 6 g de cera","65 a 70 g de infusión de manzanilla bien colada"],"steps":["Seguí el método base de crema."],"use":["Aplicar poca cantidad 1 a 3 veces al día."],"warnings":["Alergia a asteráceas: prueba previa."]},{"id":"cre-piernas","title":"Crema para piernas livianas","kind":"recipe","summary":"Para pesadez leve.","ingredients":["25 g de oleato de castaño de Indias y romero","6 a 7 g de cera","65 a 70 g de agua o infusión de hamamelis"],"steps":["Seguí el método base."],"use":["Masajear de tobillos hacia rodillas 1 a 2 veces al día."],"warnings":["No usar en úlceras ni várices muy marcadas."]},{"id":"cre-manos","title":"Crema reparadora de manos","kind":"recipe","summary":"Para resequedad por jabón, alcohol o frío.","ingredients":["25 g de oleato de caléndula","5 a 7 g de cera","60 a 65 g de infusión suave de lavanda o agua"],"steps":["Seguí el método base."],"use":["Aplicar por la noche; puede usarse con guantes de algodón."]},{"id":"cre-rostro","title":"Crema nocturna de rosa mosqueta y lavanda","kind":"recipe","summary":"Para piel madura o reseca.","ingredients":["15 g de aceite de rosa mosqueta","10 g de oleato de lavanda o caléndula","6 a 7 g de cera","65 a 70 g de agua o hidrolato de rosas"],"steps":["Seguí el método base."],"use":["Aplicar poca cantidad por la noche."],"warnings":["Piel grasa o acné severo: usar con moderación."]},{"id":"cre-pies","title":"Crema de caléndula para pies y talones","kind":"recipe","summary":"Para talones secos y pies cansados.","ingredients":["20 g de oleato de caléndula","5 g de oleato con menta suave","6 a 7 g de cera","65 a 70 g de agua"],"steps":["Seguí el método base."],"use":["Masajear plantas y talones antes de dormir."],"warnings":["No usar menta concentrada en embarazadas o niños."]}]}]},{"id":"conservacion","title":"Conservación de Hierbas Medicinales","icon":"🏷️","type":"Organización de botica","summary":"Cosecha, cuatro métodos de secado, rotulado, macerados y caja de invierno.","warning":"Descartá cualquier material con humedad, moho, olor extraño o cambios sospechosos.","sections":[{"id":"cosecha","title":"Cosechar y preparar","icon":"🌱","description":"Reglas de selección y cosecha.","items":[{"id":"con-reglas","title":"Reglas que no se negocian","kind":"guide","summary":"La humedad es el principal riesgo.","benefits":["Secar siempre a la sombra.","Usar frascos limpios y completamente secos.","Rotular nombre y fecha.","No manipular hierbas con manos mojadas."]},{"id":"con-cosecha","title":"Cuándo cosechar","kind":"guide","summary":"Condiciones sugeridas por el material.","benefits":["A la mañana, una vez que se fue el rocío.","Cuando la planta está en flor o bien verde.","Nunca después de la lluvia.","No cosechar plantas enfermas, con hongos o insectos."]}]},{"id":"secar","title":"Secar","icon":"☀️","description":"Cuatro métodos según el tipo de planta y el clima.","items":[{"id":"con-colgado","title":"Secado colgando","kind":"method","summary":"Ideal para menta, orégano, romero, tomillo, cedrón y salvia.","steps":["Hacé ramitos pequeños.","Atalos y colgalos boca abajo.","Dejá 5 a 10 días según el clima.","Guardá cuando la hoja cruja al apretarla."]},{"id":"con-bandeja","title":"Secado en bandeja","kind":"method","summary":"Ideal para flores y hojas delicadas.","steps":["Colocá una sola capa sobre papel o rejilla.","No amontones.","Girá cada 1 a 2 días.","Dejá 4 a 7 días."]},{"id":"con-horno","title":"Secado rápido en horno bajo","kind":"method","summary":"Método de emergencia para días húmedos.","steps":["Usá el horno al mínimo.","Colocá la bandeja y dejá la puerta apenas abierta.","Controlá cada 5 minutos.","Retirá a los 10 a 20 minutos y dejá enfriar antes de guardar."],"warnings":["Puede perderse parte del aroma."]},{"id":"con-deshidratador","title":"Secado en deshidratador","kind":"method","summary":"Método cómodo si se dispone del equipo.","steps":["Distribuí las hierbas.","Programá entre 35 y 45 °C.","Dejá entre 2 y 5 horas."]}]},{"id":"guardar","title":"Guardar y rotular","icon":"🏷️","description":"Envases, rótulos y control de secado.","items":[{"id":"con-envases","title":"Envases y rótulos","kind":"guide","summary":"Cada frasco debe poder identificarse sin dudas.","steps":["Usá vidrio con tapa a rosca o vidrio ámbar si hay mucha luz.","Evitá plástico blando, tapas flojas y recipientes húmedos.","Rotulá nombre, parte utilizada, fecha, vencimiento y uso."]},{"id":"con-seco","title":"Cómo saber si está bien seco","kind":"guide","summary":"Señales para decidir si puede guardarse.","benefits":["La hoja se quiebra.","No se pega al dedo.","No tiene olor a humedad.","El frasco no se empaña."],"warnings":["Si el frasco se empaña, volver al secado."]}]},{"id":"aceites","title":"Aceites medicinales","icon":"🫙","description":"Macerados en aceite.","items":[{"id":"con-aceite-base","title":"Aceite medicinal base","kind":"recipe","summary":"Macerado para uso externo.","ingredients":["1 taza de planta seca triturada","250 ml de aceite","Frasco limpio y seco"],"steps":["Llená el frasco con la planta.","Cubrí por completo con aceite.","Macerá 3 a 4 semanas en oscuridad y agitá a diario.","Colá y guardá en frasco oscuro."],"conservation":["6 a 12 meses."]},{"id":"con-calendula","title":"Aceite de caléndula","kind":"recipe","summary":"Para piel sensible, picazón, irritación y resequedad leve.","ingredients":["1 taza de pétalos secos","250 ml de aceite de oliva o girasol"],"steps":["Aplicá el método base durante 3 semanas."]},{"id":"con-romero","title":"Aceite de romero","kind":"recipe","summary":"Para masaje en articulaciones y piernas cansadas.","ingredients":["1 taza de romero seco","250 ml de aceite"],"steps":["Aplicá el método base."],"use":["Masajear la zona hasta 2 veces al día."]},{"id":"con-eucalipto","title":"Aceite de eucalipto","kind":"recipe","summary":"Para masaje externo en pecho y espalda.","ingredients":["1 taza de hojas secas y rotas","250 ml de aceite"],"steps":["Aplicá el método base."],"warnings":["No usar sin diluir en bebés pequeños."]}]},{"id":"vinagres","title":"Vinagres y tinturas","icon":"🧪","description":"Preparados de mayor conservación.","items":[{"id":"con-vinagre-base","title":"Vinagre medicinal base","kind":"recipe","summary":"Extracto en vinagre para uso doméstico.","ingredients":["1 parte de hierba seca","3 partes de vinagre de manzana"],"steps":["Cubrí la hierba con vinagre.","Macerá 2 a 3 semanas.","Colá y guardá oscuro."],"conservation":["12 meses."]},{"id":"con-vinagre-romero","title":"Vinagre de romero para piernas","kind":"recipe","summary":"Para masaje diluido.","ingredients":["1/2 taza de romero seco","1 y 1/2 taza de vinagre de manzana"],"steps":["Aplicá el método base."],"use":["Diluir 1 parte de vinagre en 3 partes de agua."]},{"id":"con-vinagre-salvia","title":"Vinagre de salvia para el pelo","kind":"recipe","summary":"Para brillo y cuero cabelludo pesado.","ingredients":["1/2 taza de salvia seca","1 y 1/2 taza de vinagre"],"steps":["Aplicá el método base."],"use":["Después del shampoo, diluir 1 parte en 4 partes de agua y enjuagar."]},{"id":"con-tintura","title":"Tintura de conservación prolongada","kind":"method","summary":"Formato opcional de larga duración.","ingredients":["1 parte de planta seca","5 partes de alcohol apto"],"steps":["Macerá 3 a 4 semanas.","Colá y guardá en gotero oscuro."],"conservation":["Hasta 2 años."]}]},{"id":"botica","title":"Revisar mi botica","icon":"📦","description":"Caja de invierno, duraciones y errores.","items":[{"id":"con-caja","title":"Armá tu caja de invierno","kind":"guide","summary":"Dejá preparados los recursos antes del frío.","ingredients":["Manzanilla seca","Eucalipto seco","Romero o tomillo seco","Caléndula seca","Aceite de caléndula","Vinagre de romero","Mezcla para vapor","Salvia","Bolsita de lavanda"],"steps":["Guardá todo en una caja o canasto.","Rotulá cada frasco.","Pegá una guía rápida en la tapa."]},{"id":"con-duracion","title":"Duraciones orientativas","kind":"guide","summary":"Tiempos indicados en el material.","benefits":["Hierba seca: 9 a 12 meses.","Aceite medicinal: 6 a 12 meses.","Vinagre medicinal: 12 meses.","Tintura: 24 meses.","Sahumerios y mezclas secas: 12 meses."],"warnings":["Moho, olor desagradable o cambio extraño de color: descartar."]},{"id":"con-errores","title":"Errores frecuentes","kind":"guide","summary":"Qué evitar.","warnings":["Guardar mientras todavía está tibio.","Guardar sin nombre.","Hacer aceites con planta fresca.","Dejar frascos al sol.","No respetar el tiempo de maceración."]}]}]},{"id":"aromaterapia","title":"Aromaterapia de Uso Medicinal","icon":"🌸","type":"Uso olfativo, ambiental y tópico diluido","summary":"Fichas de aceites, métodos y fórmulas para sueño, ánimo, foco, tensión y hogar.","warning":"No ingerir, no aplicar aceites esenciales puros y ventilar. Embarazo, lactancia, bebés y mascotas requieren especial precaución.","sections":[{"id":"aceites","title":"Conocé los aceites","icon":"🌿","description":"Ocho fichas rápidas.","items":[{"id":"aro-lavanda","title":"Lavanda","kind":"profile","summary":"Se presenta para ansiedad, insomnio, irritabilidad, tensión y dolor de cabeza por estrés.","benefits":["Versátil y combinable con naranja, limón, menta e incienso."],"warnings":["Usar siempre diluida sobre la piel."]},{"id":"aro-naranja","title":"Naranja dulce","kind":"profile","summary":"Para días de ánimo bajo, irritabilidad y ambientes sin vida.","benefits":["Levanta el ánimo sin excitar.","Aroma cálido para hogares."]},{"id":"aro-limon","title":"Limón","kind":"profile","summary":"Para aire, olores de cocina, concentración y energía.","benefits":["Claridad y optimismo.","Base de sprays domésticos."]},{"id":"aro-menta","title":"Menta","kind":"profile","summary":"Para dolor de cabeza tensional, náuseas, calor y piernas cansadas.","warnings":["No usar pura en cara u ojos.","Evitar en menores de 3 años."]},{"id":"aro-eucalipto","title":"Eucalipto","kind":"profile","summary":"Para resfríos, congestión y ambientes cerrados.","warnings":["Precaución en niños pequeños."]},{"id":"aro-teatree","title":"Árbol de té","kind":"profile","summary":"Para sprays de limpieza, baño y colchones.","warnings":["No ingerir."]},{"id":"aro-incienso","title":"Incienso","kind":"profile","summary":"Para estrés profundo y prácticas de centramiento.","benefits":["El material lo presenta como un aceite de apoyo emocional."]},{"id":"aro-romero","title":"Romero","kind":"profile","summary":"Para memoria, foco y cansancio mental.","warnings":["No usar intensivamente en embarazo ni hipertensión."]}]},{"id":"metodos","title":"Métodos y dilución","icon":"📏","description":"Seis formas de uso.","items":[{"id":"aro-inhalacion","title":"Inhalación directa","kind":"method","summary":"Recurso breve.","steps":["Colocá 1 a 2 gotas en algodón.","Acercá a la nariz durante 30 segundos y descansá."]},{"id":"aro-vapor","title":"Bowl caliente","kind":"method","summary":"Uso ambiental breve.","steps":["Agregá 4 a 6 gotas en agua muy caliente.","Inhalá a unos 30 cm durante 5 minutos."]},{"id":"aro-spray-base","title":"Spray ambiental base","kind":"method","summary":"Fórmula general.","ingredients":["200 ml de agua","50 ml de alcohol o vinagre","10 a 15 gotas en total"],"steps":["Mezclá y agitá antes de usar."]},{"id":"aro-difusor","title":"Difusor","kind":"method","summary":"Uso atmosférico.","steps":["Usá 5 a 8 gotas según el ambiente.","Difundí hasta 30 minutos y ventilá."]},{"id":"aro-rollon","title":"Roll-on diluido","kind":"method","summary":"Aplicación tópica.","ingredients":["10 ml de aceite de almendras","3 a 5 gotas de la mezcla"],"use":["Aplicar en muñecas, nuca o sienes evitando ojos."]},{"id":"aro-ducha","title":"Ducha aromática","kind":"method","summary":"Uso ambiental, no sobre piel.","steps":["Colocá 2 a 3 gotas en una esquina del piso de la ducha.","Dejá que el vapor disperse el aroma."]}]},{"id":"sueno","title":"Sueño y calma","icon":"🌙","description":"Fórmulas ambientales para descanso y ansiedad.","items":[{"id":"aro-dormir","title":"Dormir toda la noche","kind":"recipe","summary":"Mezcla ambiental o spray de almohada.","ingredients":["4 gotas de lavanda","2 gotas de naranja","1 gota de incienso"],"use":["Difusor: 15 minutos antes de dormir.","Spray: 6 gotas totales en 200 ml de agua; 2 pulverizaciones."]},{"id":"aro-ansiedad","title":"Ansiedad de tarde","kind":"recipe","summary":"Calma sin buscar inducir sueño.","ingredients":["3 gotas de lavanda","2 gotas de limón","1 gota de incienso"],"use":["Inhalación directa o bowl."]},{"id":"aro-ninos","title":"Noche tranquila para niños","kind":"recipe","summary":"Spray ambiental, no sobre almohada.","ingredients":["3 gotas de lavanda","2 gotas de naranja","200 ml de agua"],"warnings":["Usar poco tiempo y con ventilación."]}]},{"id":"foco","title":"Foco y tensión","icon":"🧠","description":"Mezclas para cabeza, ánimo y productividad.","items":[{"id":"aro-cabeza","title":"Dolor de cabeza por tensión","kind":"recipe","summary":"Aplicación tópica diluida.","ingredients":["2 gotas de menta","2 gotas de lavanda","1 cdita de aceite de coco"],"steps":["Mezclá y masajeá nuca y hombros."],"warnings":["Evitar ojos y mucosas."]},{"id":"aro-animo","title":"Estado de ánimo bajo","kind":"recipe","summary":"Mezcla cítrica ambiental.","ingredients":["3 gotas de naranja","2 gotas de lavanda","1 gota de limón"],"use":["Difusor o algodón en el escritorio."]},{"id":"aro-foco","title":"Foco y productividad","kind":"recipe","summary":"Para estudio u oficina.","ingredients":["3 gotas de limón","2 gotas de menta","1 gota de romero"],"use":["Difusor durante 20 minutos."],"warnings":["Romero: precaución en embarazo e hipertensión."]}]},{"id":"hogar","title":"Aromas para el hogar","icon":"🏠","description":"Sprays y mezclas ambientales.","items":[{"id":"aro-casa","title":"Spray “casa limpia”","kind":"recipe","summary":"Para cocina, baño, colchones y cortinas.","ingredients":["200 ml de agua","50 ml de vinagre blanco","6 gotas de limón","4 gotas de árbol de té","2 gotas de lavanda"],"steps":["Mezclá en spray.","Agitá antes de usar."]},{"id":"aro-humedad","title":"Antihumedad y baño cerrado","kind":"recipe","summary":"Uso ambiental.","ingredients":["5 gotas de eucalipto","3 gotas de limón","2 gotas de árbol de té"],"use":["Difusor durante 15 minutos o bowl caliente."]},{"id":"aro-visitas","title":"Mezcla para recibir visitas","kind":"recipe","summary":"Aroma hogareño no invasivo.","ingredients":["4 gotas de naranja","3 gotas de limón","1 gota de lavanda"],"use":["Difundir 10 minutos antes."]}]},{"id":"respiratorio","title":"Respiratorio","icon":"🫁","description":"Uso ambiental breve.","items":[{"id":"aro-resfrio","title":"Inicio de resfrío","kind":"recipe","summary":"Uso ambiental fuera del alcance.","ingredients":["2 gotas de eucalipto","2 gotas de limón"],"use":["Agregar a un bowl caliente."],"warnings":["No acercar a bebés ni niños pequeños."]}]}]},{"id":"femenina","title":"Guía Herbal Femenina","icon":"🌺","type":"Ciclo y bienestar femenino","summary":"Preparaciones organizadas para dolor menstrual, SPM, menopausia, sueño y retención.","warning":"Embarazo, lactancia, búsqueda de embarazo, medicación o síntomas intensos requieren consulta antes de usar plantas.","sections":[{"id":"menstrual","title":"Dolor menstrual","icon":"🌸","description":"Infusiones y compresas.","items":[{"id":"fem-utero","title":"Infusión “Útero tranquilo”","kind":"recipe","summary":"Para dolor menstrual leve.","ingredients":["1 cdita de manzanilla","1 cdita de salvia","1 cdita de menta","1 rodaja de jengibre","250 ml de agua"],"steps":["Colocá las hierbas.","Agregá agua caliente.","Tapá 10 minutos y colá."],"use":["2 a 3 tazas el día previo y el primer día de menstruación."],"warnings":["No usar salvia en embarazo, lactancia o búsqueda de embarazo sin consulta."]},{"id":"fem-piernas","title":"Tisana “Dolor que baja a las piernas”","kind":"recipe","summary":"Para tensión que se extiende a espalda o piernas.","ingredients":["1 cdita de valeriana o melisa","1 cdita de orégano","1 cdita de manzanilla","Agua caliente"],"steps":["Infusioná 12 minutos y colá."],"warnings":["Orégano en dosis altas: no usar en embarazo."]},{"id":"fem-compresa","title":"Compresa caliente de romero y laurel","kind":"recipe","summary":"Calor local para vientre bajo.","ingredients":["1 litro de agua","1 rama de romero","3 hojas de laurel","Paño"],"steps":["Herví 10 minutos.","Dejá templar.","Mojá y escurrí el paño.","Aplicá 15 minutos."]},{"id":"fem-emergencia","title":"Mezcla de emergencia menstrual","kind":"recipe","summary":"Versión rápida para trabajo o viaje.","ingredients":["1 saquito de manzanilla","1 saquito de tilo","1 cdita de jengibre rallado","1 cdita de miel"],"steps":["Prepará como infusión y tomá tibio."]}]},{"id":"spm","title":"SPM y cambios de humor","icon":"🌿","description":"Apoyo digestivo y nervioso.","items":[{"id":"fem-higado","title":"Infusión “Hígado femenino”","kind":"recipe","summary":"Para días previos a la menstruación y sensación de carga.","ingredients":["1 cdita de diente de león","1 cdita de manzanilla","1 cdita de milenrama, si hay","Jugo de 1/2 limón"],"steps":["Infusioná 10 minutos.","Colá y agregá limón."],"use":["1 taza por la mañana y 1 por la tarde durante 7 a 10 días previos."]},{"id":"fem-tonico","title":"Tónico de equilibrio hormonal suave","kind":"recipe","summary":"Preparación casera para calma del sistema nervioso.","ingredients":["1 cda de salvia","1 cda de orégano","1 cda de melisa","500 ml de agua"],"steps":["Herví suavemente 3 a 4 minutos.","Reposá 15 minutos.","Colá y refrigerá."],"use":["1/2 taza por la mañana y 1/2 por la tarde durante 5 días."],"warnings":["No reemplaza tratamiento médico."]},{"id":"fem-pies","title":"Baño de pies para descargar el ciclo","kind":"recipe","summary":"Para piernas pesadas y carga emocional.","steps":["Prepará agua caliente con las hierbas indicadas en el bono.","Sumergí los pies 15 a 20 minutos.","Respirá lentamente."]}]},{"id":"menopausia","title":"Menopausia y sofocos","icon":"🔥","description":"Fórmulas para sofocos, noche y calor.","items":[{"id":"fem-sofocos","title":"Infusión “Calorones fuera”","kind":"recipe","summary":"Para sofocos menopáusicos.","ingredients":["2 cditas de salvia","1 cdita de melisa","1 cdita de manzanilla","250 ml de agua"],"steps":["Infusioná tapado 10 minutos.","Colá."],"use":["2 veces al día."],"warnings":["No usar en embarazo, lactancia o antecedente de cáncer hormonodependiente sin consulta."]},{"id":"fem-noche","title":"Elixir “Noche tranquila”","kind":"recipe","summary":"Para despertares nocturnos con calor o ansiedad.","ingredients":["1 cdita de tilo","1 cdita de lavanda","1 cdita de pasiflora o valeriana","1 taza de agua"],"steps":["Infusioná 10 minutos y colá."],"use":["Tomar 30 a 40 minutos antes de dormir."]},{"id":"fem-fresca","title":"Bebida fresca anti-irritabilidad","kind":"recipe","summary":"Para días de calor y bochornos.","ingredients":["1 litro de agua","1 pepino en rodajas","1 ramita de menta","1 cdita de hinojo","1 limón en rodajas"],"steps":["Colocá todo en una jarra.","Reposá 2 horas en heladera."],"use":["Tomar durante el día."]},{"id":"fem-asiento","title":"Baño de asiento de manzanilla y rosa","kind":"recipe","summary":"Para sequedad o incomodidad leve externa.","ingredients":["2 litros de agua tibia","2 cdas de manzanilla","1 cda de pétalos de rosa","1 cdita de aceite de coco, opcional"],"steps":["Colocá las hierbas en agua tibia.","Sentate 10 a 15 minutos.","Secá sin frotar."]}]},{"id":"retencion","title":"Retención e hinchazón","icon":"💧","description":"Bebidas y compresas.","items":[{"id":"fem-diuretica","title":"Infusión diurética suave","kind":"recipe","summary":"Para retención e hinchazón leve.","ingredients":["1 cdita de cola de caballo","1 cdita de perejil fresco","1 rodaja de limón"],"steps":["Infusioná 8 a 10 minutos.","Colá."],"use":["Tomar por la mañana."],"warnings":["No prolongar cola de caballo sin supervisión."]},{"id":"fem-detox","title":"Agua de apio y manzana","kind":"recipe","summary":"Bebida para acompañar hidratación y tránsito.","ingredients":["1 tallo de apio","1/2 manzana verde","1 litro de agua","1 limón"],"steps":["Licuá apio y manzana con poca agua.","Completá la jarra y agregá limón."]},{"id":"fem-compresa-fria","title":"Compresa fría para piernas","kind":"recipe","summary":"Para sensación de piernas pesadas.","ingredients":["Agua fría","1 cda de vinagre de manzana","1 cda de romero o 2 gotas de aceite esencial","Paño"],"steps":["Mezclá.","Mojá el paño.","Envolvé pantorrillas 10 minutos."]}]},{"id":"seguridad","title":"Seguridad femenina","icon":"🛡️","description":"Recordatorios antes de elegir una receta.","items":[{"id":"fem-seguridad","title":"Antes de usar","kind":"guide","summary":"El material indica revisar siempre embarazo, búsqueda de embarazo, lactancia, medicación, presión arterial y anticoagulantes.","warnings":["Dolor menstrual muy intenso, sangrado abundante o fuera de fecha, ciclos muy irregulares o síntomas nuevos requieren evaluación."]}]}]},{"id":"belleza","title":"Belleza Natural con Hierbas Medicinales","icon":"✨","type":"Cuidado cosmético","summary":"Pomadas, mascarillas, tónicos capilares, exfoliantes y preparados rápidos.","warning":"Uso externo. Hacé prueba de sensibilidad y suspendé ante irritación. Los productos con agua duran poco.","sections":[{"id":"pomadas","title":"Pomadas","icon":"🧴","description":"Base y variantes.","items":[{"id":"bel-pomada","title":"Pomada hidratante herbal base","kind":"recipe","summary":"Para manos, codos, talones y labios según la variante.","ingredients":["40 g de aceite de caléndula u oliva","20 g de manteca de karité o cacao","15 g de cera de abejas","5 a 10 gotas de aceite esencial, opcional"],"steps":["Fundí aceite, manteca y cera a baño María.","Retirá y dejá entibiar.","Agregá opcionales.","Envasá y dejá enfriar sin tapa."],"conservation":["3 a 6 meses."],"warnings":["Uso externo."]},{"id":"bel-invierno","title":"Pomada para piel muy seca de invierno","kind":"recipe","summary":"Variante más grasa.","ingredients":["40 g de aceite de almendras","30 g de manteca de karité","20 g de cera","10 gotas de lavanda"],"steps":["Aplicá el método de la pomada base."]},{"id":"bel-talones","title":"Pomada para talones y codos","kind":"recipe","summary":"Variante para zonas ásperas.","ingredients":["40 g de aceite de romero","30 g de manteca de cacao","20 g de cera","1 cdita de almidón de maíz"],"steps":["Aplicá el método de la pomada base."]}]},{"id":"mascarillas","title":"Mascarillas","icon":"🌸","description":"Preparaciones para distintos tipos de piel.","items":[{"id":"bel-polvo","title":"Mascarilla herbal en polvo","kind":"recipe","summary":"Base seca para preparar al momento.","ingredients":["2 cdas de avena fina","1 cda de arcilla blanca","1 cda de manzanilla o caléndula molida","1 cdita de cúrcuma, opcional"],"steps":["Mezclá y guardá en frasco seco.","Para usar, mezclá 1 cda con 1 a 2 cdas de líquido.","Aplicá 10 a 15 minutos y retirala."],"conservation":["Base seca: 3 meses."]},{"id":"bel-relleno","title":"Mascarilla de avena y miel","kind":"recipe","summary":"Para hidratación y nutrición.","ingredients":["1 cda de avena molida","1 cda de miel","1 cdita de rosa mosqueta o almendra","1 cdita de aloe, opcional"],"steps":["Mezclá hasta formar pasta.","Aplicá en cara y cuello 15 minutos.","Retirá con paño tibio."]},{"id":"bel-manchas","title":"Mascarilla para piel manchada no sensible","kind":"recipe","summary":"Uso ocasional y nocturno.","ingredients":["1 cda de arcilla blanca","1 cda de infusión de perejil o manzanilla","5 gotas de limón","1/2 cdita de cúrcuma"],"steps":["Mezclá.","Aplicá 8 a 10 minutos.","Retirá e hidratá."],"warnings":["No usar en piel sensible, todos los días ni antes de exponerse al sol."]}]},{"id":"cabello","title":"Tónicos capilares","icon":"🌿","description":"Tónico fortalecedor y spray de brillo.","items":[{"id":"bel-tonico","title":"Tónico capilar “crece y fortalece”","kind":"recipe","summary":"Sin alcohol, para cuero cabelludo.","ingredients":["2 cdas de romero seco","2 cdas de ortiga o laurel","1 cda de lavanda, opcional","500 ml de agua"],"steps":["Herví suavemente 5 minutos.","Reposá tapado 30 minutos.","Colá y pasá a spray."],"use":["Aplicar en cuero cabelludo y masajear 2 a 3 minutos, 3 a 4 veces por semana."],"conservation":["7 días en heladera."]},{"id":"bel-brillo","title":"Spray capilar de brillo","kind":"recipe","summary":"Para medios y puntas.","ingredients":["100 ml de infusión de romero","1 cdita de vinagre de manzana","5 gotas de romero o lavanda"],"steps":["Mezclá y agitá."],"use":["Aplicar poca cantidad en medios y puntas."]}]},{"id":"manos","title":"Manos y exfoliantes","icon":"🤲","description":"Rituales para manos, pies y codos.","items":[{"id":"bel-exfoliante","title":"Exfoliante de manos de cocina","kind":"recipe","summary":"Para manos expuestas a agua y olores.","ingredients":["3 cdas de azúcar o sal fina","2 cdas de aceite","1 cda de limón o vinagre","1 cdita de bicarbonato, opcional","5 gotas de limón o lavanda"],"steps":["Mezclá granulado y aceite.","Agregá el líquido y el opcional.","Masajeá manos secas y enjuagá."],"warnings":["No usar en cara ni sobre lastimaduras."]},{"id":"bel-cafe","title":"Exfoliante de café y menta","kind":"recipe","summary":"Para manos, pies y codos.","ingredients":["2 cdas de café usado bien seco","2 cdas de azúcar","2 cdas de aceite","4 a 5 gotas de menta"],"steps":["Mezclá y usá sobre piel íntegra."]},{"id":"bel-bano-manos","title":"Baño nutritivo de manos","kind":"recipe","summary":"Ritual de 10 minutos.","ingredients":["1 litro de agua tibia","1 cda de aceite de oliva","1 cda de caléndula","1 cdita de miel"],"steps":["Mezclá en un bowl.","Sumergí las manos 10 minutos.","Secá y aplicá pomada."]}]},{"id":"extras","title":"Labios, spray y sérum","icon":"💧","description":"Tres extras rápidos.","items":[{"id":"bel-balsamo","title":"Bálsamo labial herbal","kind":"recipe","summary":"Versión pequeña de la pomada.","ingredients":["1 cda de aceite de caléndula","1 cda de manteca de karité","1 cdita de cera","1 gota de lavanda"],"steps":["Aplicá el método de la pomada base."]},{"id":"bel-spray-facial","title":"Spray facial refrescante","kind":"recipe","summary":"Preparación refrigerada.","ingredients":["100 ml de manzanilla fría","1 cdita de gel de aloe","3 gotas de lavanda","5 gotas de glicerina, opcional"],"steps":["Mezclá y agitá."],"conservation":["5 a 7 días en heladera."]},{"id":"bel-serum","title":"Sérum nocturno simple","kind":"recipe","summary":"Aplicación en pocas gotas.","ingredients":["2 cdas de jojoba o almendra","1/2 cdita de vitamina E","3 gotas de rosa mosqueta"],"steps":["Mezclá."],"use":["Aplicar 2 a 3 gotas sobre el rostro limpio."]}]},{"id":"seguridad","title":"Según tu piel y seguridad","icon":"🛡️","description":"Adaptaciones del material.","items":[{"id":"bel-seguridad","title":"Reglas de uso","kind":"guide","summary":"Ajustá la receta a la situación.","benefits":["Embarazo y lactancia: fórmulas sin aceites esenciales fuertes.","Niños: no usar exfoliantes con sal y limón; elegir avena y aceite.","Rosácea o acné activo: no exfoliar; usar opciones calmantes.","Todo lo que lleva agua dura alrededor de una semana en heladera; aceite y cera duran meses."]}]}]},{"id":"energetica","title":"Baños, Sahumos y Limpiezas Energéticas","icon":"🕯️","type":"Práctica tradicional y energética","summary":"Baños, sahumerios y rituales presentados como prácticas hogareñas, no médicas.","warning":"Ventilá, evitá humo cerca de bebés, personas con problemas respiratorios y mascotas. Nunca dejes fuego o velas sin supervisión.","sections":[{"id":"banos","title":"Baños de descarga","icon":"🛁","description":"Siete baños del cuello hacia abajo.","items":[{"id":"ene-bano-sal","title":"Baño de sal y laurel","kind":"recipe","summary":"Descarga rápida.","ingredients":["3 litros de agua caliente","3 cdas de sal gruesa","5 hojas de laurel","Vinagre de manzana, opcional"],"steps":["Disolvé la sal.","Agregá laurel 5 minutos.","Después de bañarte, verté del cuello hacia abajo.","Dejá secar al aire o con toalla limpia."]},{"id":"ene-bano-romero","title":"Baño de romero y ruda","kind":"recipe","summary":"Protección y corte según el marco energético del material.","ingredients":["1 rama de romero","1 rama de ruda","3 litros de agua","1 pizca de sal"],"steps":["Herví el agua.","Apagá, agregá las hierbas y reposá 10 minutos.","Colá y verté del cuello hacia abajo."],"warnings":["No usar todos los días."]},{"id":"ene-bano-flores","title":"Baño dulce de flores","kind":"recipe","summary":"Práctica de suavidad y renovación.","ingredients":["1 litro de agua tibia","Pétalos de rosa","1 cda de miel","3 gotas de vainilla o agua de rosas"],"steps":["Mezclá.","Verté al final del baño.","Dejá secar al aire."]},{"id":"ene-bano-cafe","title":"Baño de café y canela","kind":"recipe","summary":"Para cansancio y exposición pública según el material.","ingredients":["2 tazas de café fuerte","1 cdita de canela o una rama","1 litro de agua tibia"],"steps":["Mezclá y verté del cuello hacia abajo."],"warnings":["Puede resultar activante por la noche."]},{"id":"ene-bano-lavanda","title":"Baño de lavanda y manzanilla","kind":"recipe","summary":"Descarga emocional.","ingredients":["2 saquitos de manzanilla","1 cda de lavanda o 3 gotas de aceite esencial","2 litros de agua"],"steps":["Prepará una infusión grande.","Agregá lavanda.","Dejá templar y verté del cuello hacia abajo."]},{"id":"ene-bano-limon","title":"Baño de limón y salvia","kind":"recipe","summary":"Corte de un día pesado.","ingredients":["3 rodajas de limón","1 puñado de salvia o romero","3 litros de agua"],"steps":["Reposá todo en agua caliente 7 a 10 minutos.","Verté del cuello hacia abajo."]},{"id":"ene-bano-cierre","title":"Baño “cierra el cuerpo”","kind":"recipe","summary":"Para después de atender público.","ingredients":["1 litro de agua","1 chorrito de alcohol o colonia","3 hojas de laurel","1 pizca de sal"],"steps":["Mezclá y verté del cuello hacia abajo."]}]},{"id":"sahumos","title":"Sahumerios caseros","icon":"🌫️","description":"Siete mezclas del material.","items":[{"id":"ene-sahumo-basico","title":"Sahumerio de limpieza básica","kind":"recipe","summary":"","ingredients":["Laurel seco","Romero seco","Sal gruesa"],"steps":["Prendé carbón o una latita segura.","Poné primero la sal.","Agregá laurel y romero.","Recorré de adentro hacia afuera."]},{"id":"ene-sahumo-viejo","title":"Sahumerio “cortá con lo viejo”","kind":"recipe","summary":"","ingredients":["3 hojas de laurel","Cáscara de naranja seca","Canela"],"steps":["Colocá en el brasero.","Pasá por puertas, placares y escritorio."]},{"id":"ene-sahumo-proteccion","title":"Sahumerio de protección del hogar","kind":"recipe","summary":"","ingredients":["Romero","3 a 4 granos de pimienta negra","1 pizca de sal"],"steps":["Colocá todo junto.","Pasá por puertas y ventanas."],"warnings":["No abusar si hay mascotas."]},{"id":"ene-sahumo-armonia","title":"Sahumerio de armonía familiar","kind":"recipe","summary":"","ingredients":["Lavanda seca","Manzanilla","1 cdita de azúcar"],"steps":["Poné primero el azúcar.","Agregá lavanda y manzanilla.","Pasá por comedor y cocina."]},{"id":"ene-sahumo-venta","title":"Sahumerio de venta o prosperidad","kind":"recipe","summary":"","ingredients":["Laurel","Cáscara de mandarina o naranja","1 rama de canela"],"steps":["Usá en zona de trabajo, puerta, teléfono o computadora."],"use":["El material propone 1 a 2 veces por semana."]},{"id":"ene-sahumo-profundo","title":"Sahumerio de limpieza profunda","kind":"recipe","summary":"","ingredients":["Ruda seca","Romero","Sal gruesa","Ajo con cáscara, opcional"],"steps":["Sahumá rápidamente.","Ventilá al finalizar."]},{"id":"ene-sahumo-dormir","title":"Sahumerio para dormir mejor","kind":"recipe","summary":"","ingredients":["Lavanda","Laurel","1 hoja de salvia"],"steps":["Usá en el dormitorio 30 minutos antes de dormir.","Ventilá.","Ingresá después."]}]},{"id":"rituales","title":"Rituales y manos","icon":"🕯️","description":"Cierre de ciclos y limpieza después de atender gente.","items":[{"id":"ene-luna","title":"Ritual de luna llena","kind":"recipe","summary":"Práctica de descarga y cierre de ciclo.","ingredients":["1 vela blanca","1 vaso de agua","Sahumerio de limpieza básica","Papel y birome"],"steps":["Sahumá el lugar.","Encendé la vela en un soporte seguro.","Escribí lo que querés soltar.","Colocá el papel debajo del vaso.","Al día siguiente descartá el agua y rompé el papel."],"warnings":["Nunca dejes una vela sin supervisión."]},{"id":"ene-manos-rapida","title":"Limpieza rápida de manos","kind":"recipe","summary":"","ingredients":["1 cdita de sal fina","3 gotas de limón","Agua"],"steps":["Frotá sal, limón y agua en palmas y muñecas.","Enjuagá."]},{"id":"ene-manos-pro","title":"Frasco para manos durante la jornada","kind":"recipe","summary":"","ingredients":["200 ml de agua","2 cdas de sal","5 hojas de laurel","5 gotas de lavanda"],"steps":["Mezclá en un frasco.","Mojá las manos al terminar cada atención y secá."]},{"id":"ene-spray","title":"Spray corta-energía","kind":"recipe","summary":"","ingredients":["100 ml de alcohol o vodka","10 gotas de lavanda","5 gotas de limón","3 gotas de incienso"],"steps":["Mezclá en un spray.","Pulverizá en manos, hombros y detrás del cuello."],"warnings":["No aplicar en ojos ni mucosas."]}]},{"id":"intencion","title":"Elegir según la intención","icon":"✨","description":"Mapa de acceso rápido.","items":[{"id":"ene-mapa","title":"Qué práctica elegir","kind":"guide","summary":"Usá este mapa como índice del bonus.","benefits":["Cansancio o día pesado: baño de sal y laurel.","Descarga emocional: lavanda y manzanilla.","Ambiente cargado: sahumerio básico.","Armonía familiar: lavanda, manzanilla y azúcar.","Cierre de etapa: ritual de luna llena.","Después de atender gente: limpieza de manos."]}]},{"id":"seguridad","title":"Seguridad","icon":"🛡️","description":"Límites de estas prácticas.","items":[{"id":"ene-seguridad","title":"Antes de empezar","kind":"guide","summary":"Todo este contenido es de uso hogareño y energético, no médico.","warnings":["Baños siempre del cuello hacia abajo.","No verter hierbas calientes sobre la cabeza.","Embarazo o presión baja: elegir solo hierbas suaves y consultar.","Ventilar después de sahumar.","Evitar humo alrededor de bebés, personas con problemas respiratorios y animales."]}]}]}]};
(() => {
'use strict';
const RECIPES=window.RECIPES||[];
const INGREDIENTS=window.INGREDIENTS||[];
const LIB=window.APP_LIBRARY||{plants:[],preparations:[],bonuses:[],safety:{},categories:[]};
const KEYS={onboarded:'ema_onboarded_v4',favorites:'ema_favorites_v1',pantry:'ema_pantry_v1',recent:'ema_recent_v1',prepared:'ema_prepared_v1',bonusFavorites:'ema_bonus_favorites_v1',shopping:'ema_shopping_v1',demo:'ema_demo_v1'};
const previewMode=new URLSearchParams(location.search).has('preview');
const state={route:'home',favorites:new Set(loadJSON(KEYS.favorites,[])),pantry:new Set(loadJSON(KEYS.pantry,[])),recent:loadJSON(KEYS.recent,[]),prepared:loadJSON(KEYS.prepared,[]),bonusFavorites:new Set(loadJSON(KEYS.bonusFavorites,[])),shopping:loadJSON(KEYS.shopping,[]),consult:{step:1,category:'',subcategory:'',person:'adult',pregnancy:false,medication:false,chronic:false,severe:false},libraryTab:'plants',recipeFilter:{category:'all',subcategory:'all',query:'',page:1,favoriteOnly:false},pantryQuery:'',libraryQuery:'',bonusId:null,bonusSection:'all',bonusItemId:null,bonusQuery:'',bonusAgeMonths:60};
const main=document.getElementById('app-main'),modalRoot=document.getElementById('modal-root'),toastEl=document.getElementById('toast');
function loadJSON(k,f){try{const v=localStorage.getItem(k);return v?JSON.parse(v):f}catch{return f}}
function saveJSON(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){console.warn(e)}}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function norm(v=''){return String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function list(items,ordered=false){if(!items?.length)return '<p class="muted">No especificado en el material.</p>';const tag=ordered?'ol':'ul';return `<${tag}>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</${tag}>`}
function toast(m){toastEl.textContent=m;toastEl.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>toastEl.classList.remove('show'),2500)}
function recipeById(id){return RECIPES.find(r=>r.id===Number(id))}
function setRoute(route){state.route=route;state.bonusId=null;state.bonusItemId=null;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route===route));render();window.scrollTo({top:0,behavior:'smooth'})}
function imageForPlant(p){return p.imageData||p.image||'./icon-512.png'}
function recipeCard(r,extra=''){const fav=state.favorites.has(r.id);return `<article class="recipe-card" data-open-recipe="${r.id}"><div class="recipe-icon">${esc(r.icon||'🌱')}</div><div class="recipe-copy"><h3>${esc(r.title)}</h3><p>${esc(r.subcategory)} · ${esc(r.method)}</p><div class="recipe-tags"><span class="tag">Receta ${r.id}</span>${r.yield?`<span class="tag">${esc(r.yield)}</span>`:''}${extra}</div></div><button class="favorite-button ${fav?'active':''}" data-favorite="${r.id}" aria-label="${fav?'Quitar de favoritos':'Agregar a favoritos'}">${fav?'★':'☆'}</button></article>`}
function render(){if(state.route==='home')renderHome();else if(state.route==='consult')renderConsult();else if(state.route==='pantry')renderPantry();else renderLibrary()}
function renderHome(){const favs=RECIPES.filter(r=>state.favorites.has(r.id)).slice(0,4);const recent=state.recent.map(recipeById).filter(Boolean).slice(0,4);main.innerHTML=`<section class="hero"><div class="hero-content"><p class="eyebrow">Sabiduría ancestral · criterio responsable</p><h1>¿Qué necesitás resolver hoy?</h1><p>Encontrá el malestar, revisá precauciones y seguí preparaciones paso a paso.</p><div class="hero-actions"><button class="btn btn-primary" data-route="consult">Consultar un malestar</button><button class="btn btn-secondary" data-route="library">Explorar la biblioteca</button></div></div></section><form class="search-box home-search" id="home-search-form"><span>⌕</span><input name="q" placeholder="Buscá por síntoma, planta o preparación"><button aria-label="Buscar">→</button></form><section class="section"><div class="section-header"><div><h2>Explorá por sistema</h2><p>330 recetas organizadas por malestar.</p></div></div><div class="category-grid">${LIB.categories.map(c=>`<button class="category-card" data-category="${esc(c.name)}"><span class="emoji">${c.icon}</span><strong>${esc(c.name)}</strong><small>Recetas ${c.start}–${c.end}</small></button>`).join('')}</div></section><section class="section"><div class="section-header"><div><h2>Bonos interactivos</h2><p>Ocho guías transformadas en herramientas de consulta.</p></div><button class="text-button" data-open-bonuses>Ver bonos</button></div><div class="bonus-mini-grid">${LIB.bonuses.slice(0,4).map(b=>`<button class="bonus-mini-card" data-open-bonus="${b.id}"><span>${b.icon}</span><strong>${esc(b.title)}</strong></button>`).join('')}</div></section><section class="section"><div class="pantry-summary"><div class="metric"><strong>${state.pantry.size}</strong><small>ingredientes en tu botica</small></div><div class="metric"><strong>${state.shopping.length}</strong><small>ingredientes en compras</small></div></div></section><section class="section"><div class="section-header"><div><h2>Tus favoritas</h2><p>Lo que querés tener a mano.</p></div></div><div class="card-grid">${favs.length?favs.map(recipeCard).join(''):`<div class="empty-state"><div class="empty-icon">☆</div><h3>Todavía no guardaste recetas</h3><p>Tocá la estrella de una preparación.</p></div>`}</div></section>${recent.length?`<section class="section"><div class="section-header"><div><h2>Consultadas recientemente</h2></div></div><div class="card-grid">${recent.map(recipeCard).join('')}</div></section>`:''}<section class="section"><div class="alert alert-neutral"><span>🛡️</span><div><strong>Recordatorio de seguridad</strong>La app organiza contenido educativo. No diagnostica ni reemplaza atención profesional.</div></div></section>`}
function renderConsult(){if(state.consult.step===99)return renderBrowseRecipes();if(state.consult.step===1)return renderConsultStep1();if(state.consult.step===2)return renderConsultStep2();return renderConsultResults()}
function stepper(s){return `<div class="stepper"><div class="step ${s===1?'active':s>1?'done':''}">1. Malestar</div><div class="step ${s===2?'active':s>2?'done':''}">2. Seguridad</div><div class="step ${s===3?'active':''}">3. Opciones</div></div>`}
function renderConsultStep1(){const cat=LIB.categories.find(c=>c.name===state.consult.category);main.innerHTML=`<div class="page-heading"><p class="eyebrow">Índice Express</p><h1 class="page-title">Consultar un malestar</h1><p>Elegí el sistema y la molestia más cercana.</p></div>${stepper(1)}<form id="consult-step1" class="panel form-grid"><div class="field"><label for="consult-category">Sistema o área</label><select id="consult-category"><option value="">Seleccioná una opción</option>${LIB.categories.map(c=>`<option ${c.name===state.consult.category?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="consult-subcategory">Malestar</label><select id="consult-subcategory" ${cat?'':'disabled'}><option value="">Seleccioná una opción</option>${cat?cat.subcategories.map(s=>`<option ${s.name===state.consult.subcategory?'selected':''}>${esc(s.name)}</option>`).join(''):''}</select><span class="field-help">No es un diagnóstico; organiza el contenido.</span></div><button class="btn btn-primary btn-block">Revisar seguridad</button></form><section class="section"><button class="btn btn-light btn-block" data-browse-all>Ver las 330 recetas</button></section>`}
function renderConsultStep2(){main.innerHTML=`<div class="page-heading"><p class="eyebrow">Semáforo de seguridad</p><h1 class="page-title">Antes de mostrar opciones</h1><p>Estas preguntas solo identifican situaciones que requieren precaución.</p></div>${stepper(2)}<form id="consult-step2" class="panel form-grid"><fieldset class="field"><legend>¿Para quién es?</legend><div class="choice-grid">${[['adult','🧑 Adulto'],['child','🧒 Niño'],['baby','👶 Bebé'],['older','🧓 Persona mayor']].map(([v,l])=>`<div class="choice"><input type="radio" id="p-${v}" name="person" value="${v}" ${state.consult.person===v?'checked':''}><label for="p-${v}">${l}</label></div>`).join('')}</div></fieldset>${[['pregnancy','Embarazo o lactancia'],['medication','Medicación crónica'],['chronic','Enfermedad crónica relevante'],['severe','Síntoma intenso, nuevo o señal de alarma']].map(([v,l])=>`<label class="check-row"><input type="checkbox" name="${v}"> <span>${l}</span></label>`).join('')}<button class="btn btn-primary btn-block">Ver resultado</button><button type="button" class="btn btn-ghost btn-block" data-consult-back>Volver</button></form>`}
function renderConsultResults(){const s=state.consult;const red=s.severe||s.person==='baby';const amber=!red&&(s.pregnancy||s.medication||s.chronic||s.person==='child'||s.person==='older');const recipes=RECIPES.filter(r=>r.category===s.category&&r.subcategory===s.subcategory).slice(0,10);main.innerHTML=`<div class="page-heading"><p class="eyebrow">Resultado</p><h1 class="page-title">${red?'Detené la consulta casera':amber?'Avanzá con precaución':'Opciones disponibles'}</h1></div>${stepper(3)}<div class="alert ${red?'alert-red':amber?'alert-amber':'alert-green'}"><span>${red?'🔴':amber?'🟡':'🟢'}</span><div><strong>${red?'Evaluación profesional recomendada':amber?'Revisá cada preparación':'Autocuidado complementario'}</strong>${red?'La app no debe guiar una receta para esta situación.':amber?'La situación requiere revisar edad, medicación, embarazo o condición previa.':'Estas opciones corresponden al índice elegido, siempre que el malestar sea leve y conocido.'}</div></div>${!red?`<section class="section"><div class="card-grid">${recipes.map(recipeCard).join('')}</div></section>`:''}<section class="section"><button class="btn btn-light btn-block" data-new-consult>Nueva consulta</button></section>`}
function renderBrowseRecipes(){state.consult.step=99;const f=state.recipeFilter,q=norm(f.query);let rows=RECIPES.filter(r=>(f.category==='all'||r.category===f.category)&&(f.subcategory==='all'||r.subcategory===f.subcategory)&&(!f.favoriteOnly||state.favorites.has(r.id))&&(!q||norm([r.title,r.category,r.subcategory,r.method,...r.ingredients].join(' ')).includes(q)));const pages=Math.max(1,Math.ceil(rows.length/20));f.page=Math.min(f.page,pages);const view=rows.slice((f.page-1)*20,f.page*20);const cat=LIB.categories.find(c=>c.name===f.category);main.innerHTML=`<div class="page-heading"><p class="eyebrow">Biblioteca de recetas</p><h1 class="page-title">${f.favoriteOnly?'Mis favoritas':'Todas las preparaciones'}</h1><p>${rows.length} resultados.</p></div><div class="filters"><form class="search-box" id="recipe-search-form"><input name="q" value="${esc(f.query)}" placeholder="Síntoma, ingrediente o receta"><button>→</button></form><div class="chips"><button class="chip ${f.category==='all'?'active':''}" data-filter-category="all">Todo</button>${LIB.categories.map(c=>`<button class="chip ${f.category===c.name?'active':''}" data-filter-category="${esc(c.name)}">${c.icon} ${esc(c.name)}</button>`).join('')}</div>${cat?`<div class="chips"><button class="chip ${f.subcategory==='all'?'active':''}" data-filter-subcategory="all">Todos</button>${cat.subcategories.map(s=>`<button class="chip ${f.subcategory===s.name?'active':''}" data-filter-subcategory="${esc(s.name)}">${esc(s.name)}</button>`).join('')}</div>`:''}</div><div class="card-grid">${view.length?view.map(recipeCard).join(''):'<div class="empty-state"><h3>Sin resultados</h3><p>Probá otra búsqueda.</p></div>'}</div><div class="pagination"><button class="btn btn-light btn-small" data-page="${f.page-1}" ${f.page===1?'disabled':''}>Anterior</button><span>${f.page} / ${pages}</span><button class="btn btn-light btn-small" data-page="${f.page+1}" ${f.page===pages?'disabled':''}>Siguiente</button></div>`}
function renderPantry(){const q=norm(state.pantryQuery);const shown=INGREDIENTS.filter(i=>!q||norm(i.name).includes(q));const possible=RECIPES.map(r=>{const keys=r.ingredientKeys||[];const have=keys.filter(k=>state.pantry.has(k)).length;return {r,pct:keys.length?Math.round(have/keys.length*100):0}}).filter(x=>x.pct>=60).sort((a,b)=>b.pct-a.pct).slice(0,8);main.innerHTML=`<div class="page-heading"><p class="eyebrow">Inventario personal</p><h1 class="page-title">Mi botica</h1><p>Marcá ingredientes y organizá tu lista de compras.</p></div><div class="pantry-summary"><div class="metric"><strong>${state.pantry.size}</strong><small>ingredientes disponibles</small></div><div class="metric"><strong>${state.shopping.length}</strong><small>pendientes de compra</small></div></div><form class="search-box" id="pantry-search-form"><input name="q" value="${esc(state.pantryQuery)}" placeholder="Buscar ingrediente"><button>→</button></form><section class="section panel"><div class="section-header"><div><h2>Ingredientes</h2></div><button class="text-button" data-clear-pantry>Limpiar</button></div><div class="ingredient-list">${shown.map(i=>`<label class="ingredient-item"><input type="checkbox" data-pantry-key="${esc(i.key)}" ${state.pantry.has(i.key)?'checked':''}><span>${esc(i.name)}<small>${i.count} recetas</small></span></label>`).join('')}</div></section>${state.shopping.length?`<section class="section panel"><div class="section-header"><div><h2>Lista de compras</h2><p>Agregada desde los bonos.</p></div><button class="text-button" data-clear-shopping>Vaciar</button></div><div class="shopping-list">${state.shopping.map((x,i)=>`<label class="shopping-row"><input type="checkbox" data-shopping-index="${i}"><span>${esc(x)}</span></label>`).join('')}</div></section>`:''}<section class="section"><div class="section-header"><div><h2>Podés preparar</h2><p>Recetas con al menos 60 % de coincidencia.</p></div></div><div class="card-grid">${possible.length?possible.map(x=>recipeCard(x.r,`<span class="tag">${x.pct}% disponible</span>`)).join(''):'<div class="empty-state"><h3>Marcá lo que tenés</h3><p>La app calculará coincidencias.</p></div>'}</div></section>`}
function renderLibrary(){if(state.bonusId)return state.bonusItemId?renderBonusItem():renderBonus();const q=norm(state.libraryQuery);let content='';if(state.libraryTab==='plants'){const rows=LIB.plants.filter(p=>!q||norm(p.name+' '+p.uses).includes(q));content=`<div class="library-grid plant-grid">${rows.map(p=>`<button class="library-card plant-library-card" data-open-plant="${p.id}"><img class="plant-card-image" src="${imageForPlant(p)}" alt="${esc(p.name)}"><div class="plant-card-copy"><h3>${esc(p.name)}</h3><p>${esc(p.uses)}</p><span class="card-link">Ver ficha →</span></div></button>`).join('')}</div>`}else if(state.libraryTab==='preparations'){content=`<div class="library-grid">${LIB.preparations.filter(p=>!q||norm(p.title+' '+p.bestFor).includes(q)).map(p=>`<button class="library-card" data-open-preparation="${p.id}"><div class="card-top"><span class="big-icon">${p.icon}</span><div><h3>${esc(p.title)}</h3><p>${esc(p.bestFor)}</p></div></div></button>`).join('')}</div>`}else if(state.libraryTab==='bonuses'){content=`<div class="bonus-grid">${LIB.bonuses.filter(b=>!q||norm(b.title+' '+b.summary).includes(q)).map(b=>`<button class="bonus-card" data-open-bonus="${b.id}"><div class="bonus-icon">${b.icon}</div><div><p class="eyebrow">Bono interactivo</p><h3>${esc(b.title)}</h3><p>${esc(b.summary)}</p><span class="card-link">Abrir bono →</span></div></button>`).join('')}</div>`}else{content=`<div class="panel"><div class="alert alert-neutral"><span>🛡️</span><div><strong>Uso responsable</strong>La app no diagnostica, no prescribe y no reemplaza consultas.</div></div><section class="detail-section"><h3>Reglas generales</h3>${list(LIB.safety.general)}</section><section class="detail-section"><h3>Señales de alarma</h3>${list(LIB.safety.redFlags)}</section><section class="detail-section"><h3>Situaciones especiales</h3>${list(LIB.safety.specialSituations)}</section></div>`}main.innerHTML=`<div class="page-heading"><p class="eyebrow">Aprendé una vez · consultá siempre</p><h1 class="page-title">Biblioteca ancestral</h1><p>Plantas, métodos, bonos completos y reglas de seguridad.</p></div><div class="tabs">${[['plants','Plantas'],['preparations','Preparaciones'],['bonuses','Bonos'],['safety','Seguridad']].map(([id,l])=>`<button class="tab ${state.libraryTab===id?'active':''}" data-library-tab="${id}">${l}</button>`).join('')}</div>${state.libraryTab!=='safety'?`<form class="search-box" id="library-search-form"><input name="q" value="${esc(state.libraryQuery)}" placeholder="Buscar en esta sección"><button>→</button></form><div class="mt-3">${content}</div>`:content}`}
function renderBonus(){const b=LIB.bonuses.find(x=>x.id===state.bonusId);if(!b){state.bonusId=null;return renderLibrary()}const q=norm(state.bonusQuery);const age=state.bonusAgeMonths;const sec=state.bonusSection==='all'?null:b.sections.find(s=>s.id===state.bonusSection);let items=(sec?sec.items:b.sections.flatMap(s=>s.items.map(i=>({...i,_section:s.title})))).filter(i=>!q||norm(i.title+' '+(i.summary||'')+' '+(i.tags||[]).join(' ')).includes(q));if(b.ageSelector)items=items.filter(i=>(i.minAgeMonths??0)<=age&&(i.maxAgeMonths??9999)>=age);main.innerHTML=`<div class="bonus-hero"><button class="back-button" data-back-bonuses>← Bonos</button><p class="eyebrow">${esc(b.type)}</p><div class="bonus-title-row"><span>${b.icon}</span><div><h1>${esc(b.title)}</h1><p>${esc(b.summary)}</p></div></div></div><div class="alert alert-amber mt-2"><span>⚠️</span><div><strong>Límite importante</strong>${esc(b.warning)}</div></div>${b.ageSelector?`<section class="panel mt-3"><div class="field"><label for="bonus-age">Edad del niño o niña</label><select id="bonus-age">${[[3,'Menor de 6 meses'],[9,'6 a 11 meses'],[24,'1 a 3 años'],[60,'4 a 6 años'],[96,'7 años o más']].map(([v,l])=>`<option value="${v}" ${age===v?'selected':''}>${l}</option>`).join('')}</select><span class="field-help">Las preparaciones incompatibles con la edad elegida se ocultan.</span></div></section>`:''}<form class="search-box mt-3" id="bonus-search-form"><input name="q" value="${esc(state.bonusQuery)}" placeholder="Buscar dentro del bono"><button>→</button></form><div class="bonus-section-buttons"><button class="bonus-section-button ${state.bonusSection==='all'?'active':''}" data-bonus-section="all"><span>☰</span><strong>Todo</strong></button>${b.sections.map(s=>`<button class="bonus-section-button ${state.bonusSection===s.id?'active':''}" data-bonus-section="${s.id}"><span>${s.icon}</span><strong>${esc(s.title)}</strong></button>`).join('')}</div>${sec?`<div class="section-header"><div><h2>${sec.icon} ${esc(sec.title)}</h2><p>${esc(sec.description)}</p></div></div>`:''}<div class="bonus-item-grid">${items.length?items.map(i=>bonusItemCard(b,i)).join(''):'<div class="empty-state"><h3>No hay opciones para este filtro</h3><p>Cambiá la edad, sección o búsqueda.</p></div>'}</div>`}
function bonusItemCard(b,i){const key=b.id+':'+i.id;const fav=state.bonusFavorites.has(key);return `<article class="bonus-item-card" data-open-bonus-item="${i.id}"><div class="bonus-item-top"><span class="kind-pill">${i.kind==='guide'?'Guía':i.kind==='method'?'Método':i.kind==='profile'?'Ficha':'Receta'}</span><button class="favorite-button ${fav?'active':''}" data-bonus-favorite="${esc(key)}">${fav?'★':'☆'}</button></div><h3>${esc(i.title)}</h3><p>${esc(i.summary||'Abrí para ver el contenido paso a paso.')}</p>${i.minAgeMonths?`<span class="age-pill">Desde ${i.minAgeMonths<12?i.minAgeMonths+' meses':Math.floor(i.minAgeMonths/12)+' año(s)'}</span>`:''}<span class="card-link">Ver contenido →</span></article>`}
function findBonusItem(b,id){for(const s of b.sections){const i=s.items.find(x=>x.id===id);if(i)return {...i,_section:s.title,_icon:s.icon}}return null}
function renderBonusItem(){const b=LIB.bonuses.find(x=>x.id===state.bonusId),i=b&&findBonusItem(b,state.bonusItemId);if(!i){state.bonusItemId=null;return renderBonus()}const key=b.id+':'+i.id;const fav=state.bonusFavorites.has(key);main.innerHTML=`<div class="bonus-detail-page"><button class="back-button" data-back-bonus>← ${esc(b.title)}</button><div class="recipe-detail-head"><p class="eyebrow">${i._icon} ${esc(i._section)}</p><h1>${esc(i.title)}</h1><p>${esc(i.summary||'Contenido del bono.')}</p><div class="detail-actions"><button class="btn btn-primary btn-small" data-bonus-favorite="${esc(key)}">${fav?'★ Guardado':'☆ Guardar'}</button>${i.ingredients?.length?`<button class="btn btn-secondary btn-small" data-add-bonus-shopping="${i.id}">+ Faltantes a compras</button>`:''}</div></div>${i.ingredients?.length?`<section class="detail-section"><h3>Ingredientes o materiales</h3>${list(i.ingredients)}</section>`:''}${i.steps?.length?`<section class="detail-section"><h3>${i.kind==='guide'?'Cómo hacerlo':'Preparación paso a paso'}</h3>${list(i.steps,true)}</section>`:''}${i.use?.length?`<section class="detail-section"><h3>Forma de uso</h3>${list(i.use)}</section>`:''}${i.benefits?.length?`<section class="detail-section"><h3>${i.kind==='guide'?'Puntos principales':'Beneficios descritos en el material'}</h3>${list(i.benefits)}</section>`:''}${i.notes?.length?`<section class="detail-section"><h3>Notas</h3>${list(i.notes)}</section>`:''}${i.conservation?.length?`<section class="detail-section"><h3>Conservación</h3>${list(i.conservation)}</section>`:''}${i.warnings?.length?`<div class="alert alert-amber mt-3"><span>⚠️</span><div><strong>Precauciones</strong>${list(i.warnings)}</div></div>`:''}<div class="alert alert-neutral mt-3"><span>i</span><div><strong>Contenido educativo</strong>Respetá los límites del bono y consultá ante síntomas intensos, persistentes o nuevos.</div></div></div>`}
function openRecipe(id){const r=recipeById(id);if(!r)return;state.recent=[r.id,...state.recent.filter(x=>x!==r.id)].slice(0,8);saveJSON(KEYS.recent,state.recent);const fav=state.favorites.has(r.id);openModal(r.title,`<div class="recipe-detail-head"><p class="eyebrow">${esc(r.category)} · ${esc(r.subcategory)}</p><h2>${esc(r.title)}</h2><p>${esc(r.method)} ${r.yield?'· '+esc(r.yield):''}</p><div class="detail-actions"><button class="btn btn-primary btn-small" data-favorite="${r.id}">${fav?'★ Guardada':'☆ Guardar'}</button><button class="btn btn-secondary btn-small" data-mark-prepared="${r.id}">✓ Marcar preparada</button></div></div><section class="detail-section"><h3>Ingredientes</h3>${list(r.ingredients)}</section>${r.materials?.length?`<section class="detail-section"><h3>Materiales</h3>${list(r.materials)}</section>`:''}<section class="detail-section"><h3>Preparación paso a paso</h3>${list(r.preparation,true)}</section><section class="detail-section"><h3>Beneficios descritos en el recetario</h3>${list(r.benefits)}</section>${r.conservation?.length?`<section class="detail-section"><h3>Conservación</h3>${list(r.conservation)}</section>`:''}${r.precautions?.length?`<div class="alert alert-amber mt-3"><span>⚠️</span><div><strong>Precauciones</strong>${list(r.precautions)}</div></div>`:''}<div class="alert alert-neutral mt-3"><span>i</span><div><strong>Contenido educativo</strong>No reemplaza diagnóstico, tratamiento ni seguimiento profesional.</div></div>`)}
function openPlant(id){const p=LIB.plants.find(x=>x.id===Number(id));if(!p)return;const terms=norm(p.name).split(/\s+|\//).filter(x=>x.length>3);const related=RECIPES.filter(r=>terms.some(t=>norm(r.ingredients.join(' ')+' '+r.title).includes(t))).slice(0,4);openModal(p.name,`<img class="plant-detail-image" src="${imageForPlant(p)}" alt="${esc(p.name)}"><div class="recipe-detail-head plant-detail-head"><p class="eyebrow">Planta ${p.id} de 30</p><h2>${esc(p.name)}</h2><p>Ficha de consulta rápida.</p></div><section class="detail-section"><h3>Para qué se presenta</h3><p>${esc(p.uses)}</p></section><section class="detail-section"><h3>Parte utilizada</h3><p>${esc(p.part)}</p></section><section class="detail-section"><h3>Cómo usar</h3><p>${esc(p.how)}</p></section><section class="detail-section"><h3>Precaución</h3><p>${esc(p.precaution)}</p></section><section class="detail-section"><h3>Sustituto propuesto</h3><p>${esc(p.substitute)}</p></section>${related.length?`<section class="detail-section"><h3>Recetas relacionadas</h3><div class="related-links">${related.map(r=>`<button data-open-recipe="${r.id}">${esc(r.title)}</button>`).join('')}</div></section>`:''}`)}
function openPreparation(id){const p=LIB.preparations.find(x=>x.id===id);if(!p)return;openModal(p.title,`<div class="recipe-detail-head"><p class="eyebrow">Método base</p><h2>${p.icon} ${esc(p.title)}</h2><p>${esc(p.bestFor)}</p></div><section class="detail-section"><h3>Base</h3>${list(p.ingredients)}</section><section class="detail-section"><h3>Pasos</h3>${list(p.steps,true)}</section><div class="alert alert-neutral"><span>i</span><div><strong>Nota</strong>${esc(p.note)}</div></div>`)}
function openModal(title,body){modalRoot.innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal" data-modal-panel><header class="modal-header"><h2>${esc(title)}</h2><button class="modal-close">×</button></header><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden'}
function closeModal(){modalRoot.innerHTML='';document.body.style.overflow=''}
function toggleFavorite(id){id=Number(id);state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);saveJSON(KEYS.favorites,[...state.favorites]);toast('Favoritos actualizados.');render();if(modalRoot.innerHTML)openRecipe(id)}
function toggleBonusFavorite(key){state.bonusFavorites.has(key)?state.bonusFavorites.delete(key):state.bonusFavorites.add(key);saveJSON(KEYS.bonusFavorites,[...state.bonusFavorites]);toast('Guardados actualizados.');render()}
function addBonusShopping(itemId){const b=LIB.bonuses.find(x=>x.id===state.bonusId),i=b&&findBonusItem(b,itemId);if(!i?.ingredients?.length)return;const names=i.ingredients.map(x=>x.replace(/^[0-9½¼¾.,\s]+(g|ml|l|cdas?|cditas?|gotas?|tazas?|ramas?|hojas?|rodajas?|puñados?|partes?)?\s*(de\s+)?/i,'').trim()).filter(Boolean);state.shopping=[...new Set([...state.shopping,...names])];saveJSON(KEYS.shopping,state.shopping);toast('Ingredientes agregados a compras.')}
function markPrepared(id){const r=recipeById(id);if(!r)return;state.prepared.unshift({id:String(Date.now()),recipeId:r.id,createdAt:new Date().toISOString(),conservation:(r.conservation||[]).join(' ')});saveJSON(KEYS.prepared,state.prepared.slice(0,100));toast('Preparación registrada.')}
function openSettings(){openModal('Configuración',`<div class="alert alert-neutral"><span>🔒</span><div><strong>Datos locales</strong>Favoritos, botica y listas se guardan en este navegador.</div></div><div class="settings-group"><h3>Contenido</h3><div class="info-row"><span>Recetas</span><strong>${RECIPES.length}</strong></div><div class="info-row"><span>Plantas con fotografía</span><strong>${LIB.plants.length}</strong></div><div class="info-row"><span>Bonos interactivos</span><strong>${LIB.bonuses.length}</strong></div></div><div class="settings-group"><h3>Tus datos</h3><div class="settings-stack"><button class="btn btn-light btn-block" data-export>Exportar copia JSON</button><label class="btn btn-light btn-block">Importar copia<input type="file" id="import-file" accept="application/json" hidden></label><button class="btn btn-danger btn-block" data-reset-app>Borrar datos locales</button></div></div>`)}
function exportData(){const data={version:4,exportedAt:new Date().toISOString(),favorites:[...state.favorites],pantry:[...state.pantry],recent:state.recent,prepared:state.prepared,bonusFavorites:[...state.bonusFavorites],shopping:state.shopping};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='el-medico-ancestral-datos.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
async function importData(file){try{const d=JSON.parse(await file.text());state.favorites=new Set(d.favorites||[]);state.pantry=new Set(d.pantry||[]);state.recent=d.recent||[];state.prepared=d.prepared||[];state.bonusFavorites=new Set(d.bonusFavorites||[]);state.shopping=d.shopping||[];saveJSON(KEYS.favorites,[...state.favorites]);saveJSON(KEYS.pantry,[...state.pantry]);saveJSON(KEYS.recent,state.recent);saveJSON(KEYS.prepared,state.prepared);saveJSON(KEYS.bonusFavorites,[...state.bonusFavorites]);saveJSON(KEYS.shopping,state.shopping);closeModal();render();toast('Copia importada.')}catch{toast('Archivo no válido.')}}
function resetApp(){if(confirm('¿Borrar favoritos, botica, compras y registros?')){Object.values(KEYS).forEach(k=>localStorage.removeItem(k));location.reload()}}
document.addEventListener('click',e=>{const route=e.target.closest('[data-route]');if(route){setRoute(route.dataset.route);return}const cat=e.target.closest('[data-category]');if(cat){state.consult.category=cat.dataset.category;state.consult.subcategory='';state.consult.step=1;setRoute('consult');return}const rec=e.target.closest('[data-open-recipe]');if(rec&&!e.target.closest('[data-favorite]')){openRecipe(rec.dataset.openRecipe);return}const fav=e.target.closest('[data-favorite]');if(fav){e.stopPropagation();toggleFavorite(fav.dataset.favorite);return}if(e.target.closest('[data-close-modal]')&&!e.target.closest('[data-modal-panel]')||e.target.closest('.modal-close')){closeModal();return}if(e.target.closest('[data-consult-back]')){state.consult.step=1;render();return}if(e.target.closest('[data-new-consult]')){state.consult={step:1,category:'',subcategory:'',person:'adult',pregnancy:false,medication:false,chronic:false,severe:false};render();return}if(e.target.closest('[data-browse-all]')){state.recipeFilter={category:'all',subcategory:'all',query:'',page:1,favoriteOnly:false};renderBrowseRecipes();return}const fc=e.target.closest('[data-filter-category]');if(fc){state.recipeFilter.category=fc.dataset.filterCategory;state.recipeFilter.subcategory='all';state.recipeFilter.page=1;renderBrowseRecipes();return}const fs=e.target.closest('[data-filter-subcategory]');if(fs){state.recipeFilter.subcategory=fs.dataset.filterSubcategory;state.recipeFilter.page=1;renderBrowseRecipes();return}const pg=e.target.closest('[data-page]');if(pg&&!pg.disabled){state.recipeFilter.page=Number(pg.dataset.page);renderBrowseRecipes();scrollTo(0,0);return}const tab=e.target.closest('[data-library-tab]');if(tab){state.libraryTab=tab.dataset.libraryTab;state.libraryQuery='';state.bonusId=null;renderLibrary();return}const plant=e.target.closest('[data-open-plant]');if(plant){openPlant(plant.dataset.openPlant);return}const prep=e.target.closest('[data-open-preparation]');if(prep){openPreparation(prep.dataset.openPreparation);return}if(e.target.closest('[data-open-bonuses]')){state.route='library';state.libraryTab='bonuses';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route==='library'));renderLibrary();return}const bonus=e.target.closest('[data-open-bonus]');if(bonus){state.route='library';state.libraryTab='bonuses';state.bonusId=bonus.dataset.openBonus;state.bonusSection='all';state.bonusItemId=null;state.bonusQuery='';renderLibrary();scrollTo(0,0);return}if(e.target.closest('[data-back-bonuses]')){state.bonusId=null;state.bonusItemId=null;renderLibrary();return}if(e.target.closest('[data-back-bonus]')){state.bonusItemId=null;renderLibrary();return}const bs=e.target.closest('[data-bonus-section]');if(bs){state.bonusSection=bs.dataset.bonusSection;renderBonus();return}const bi=e.target.closest('[data-open-bonus-item]');if(bi&&!e.target.closest('[data-bonus-favorite]')){state.bonusItemId=bi.dataset.openBonusItem;renderBonusItem();scrollTo(0,0);return}const bf=e.target.closest('[data-bonus-favorite]');if(bf){e.stopPropagation();toggleBonusFavorite(bf.dataset.bonusFavorite);return}const sh=e.target.closest('[data-add-bonus-shopping]');if(sh){addBonusShopping(sh.dataset.addBonusShopping);return}const mp=e.target.closest('[data-mark-prepared]');if(mp){markPrepared(mp.dataset.markPrepared);return}if(e.target.closest('[data-clear-pantry]')){state.pantry.clear();saveJSON(KEYS.pantry,[]);renderPantry();return}if(e.target.closest('[data-clear-shopping]')){state.shopping=[];saveJSON(KEYS.shopping,[]);renderPantry();return}if(e.target.closest('[data-export]')){exportData();return}if(e.target.closest('[data-reset-app]')){resetApp();return}if(e.target.closest('[data-onboarding-next]')){document.querySelector('[data-onboarding-step="1"]').hidden=true;document.querySelector('[data-onboarding-step="2"]').hidden=false;return}})
document.addEventListener('change',e=>{if(e.target.id==='consult-category'){state.consult.category=e.target.value;state.consult.subcategory='';renderConsultStep1();return}if(e.target.matches('[data-pantry-key]')){e.target.checked?state.pantry.add(e.target.dataset.pantryKey):state.pantry.delete(e.target.dataset.pantryKey);saveJSON(KEYS.pantry,[...state.pantry]);return}if(e.target.matches('[data-shopping-index]')&&e.target.checked){state.shopping.splice(Number(e.target.dataset.shoppingIndex),1);saveJSON(KEYS.shopping,state.shopping);renderPantry();return}if(e.target.id==='bonus-age'){state.bonusAgeMonths=Number(e.target.value);renderBonus();return}if(e.target.id==='safety-consent'){document.getElementById('finish-onboarding').disabled=!e.target.checked;return}if(e.target.id==='import-file'&&e.target.files[0]){importData(e.target.files[0]);return}})
document.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target);if(e.target.id==='home-search-form'){state.recipeFilter={category:'all',subcategory:'all',query:fd.get('q')||'',page:1,favoriteOnly:false};state.route='consult';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route==='consult'));renderBrowseRecipes();return}if(e.target.id==='recipe-search-form'){state.recipeFilter.query=fd.get('q')||'';state.recipeFilter.page=1;renderBrowseRecipes();return}if(e.target.id==='pantry-search-form'){state.pantryQuery=fd.get('q')||'';renderPantry();return}if(e.target.id==='library-search-form'){state.libraryQuery=fd.get('q')||'';renderLibrary();return}if(e.target.id==='bonus-search-form'){state.bonusQuery=fd.get('q')||'';renderBonus();return}if(e.target.id==='consult-step1'){const c=document.getElementById('consult-category').value,s=document.getElementById('consult-subcategory').value;if(!c||!s){toast('Seleccioná sistema y malestar.');return}state.consult.category=c;state.consult.subcategory=s;state.consult.step=2;render();return}if(e.target.id==='consult-step2'){state.consult.person=fd.get('person')||'adult';state.consult.pregnancy=fd.has('pregnancy');state.consult.medication=fd.has('medication');state.consult.chronic=fd.has('chronic');state.consult.severe=fd.has('severe');state.consult.step=3;render();return}})
document.getElementById('settings-button').addEventListener('click',openSettings);document.getElementById('finish-onboarding').addEventListener('click',()=>{localStorage.setItem(KEYS.onboarded,'1');document.getElementById('onboarding').hidden=true;document.body.style.overflow='';render()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalRoot.innerHTML)closeModal()});if(!localStorage.getItem(KEYS.onboarded)&&!previewMode){document.getElementById('onboarding').hidden=false;document.body.style.overflow='hidden'}else document.getElementById('onboarding').hidden=true;render();if('serviceWorker'in navigator&&!previewMode)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(console.warn));
})();
